var HABILIDADES_LIVRO = [
  {"id":"acuidade-arma","nome":"Acuidade com Arma","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Des 13. Quando usa uma arma corpo a corpo leve ou uma arma de arremesso, você pode usar sua Destreza em vez de Força nos testes de ataque e rolagens de dano."},
  {"id":"arma-secundaria-grande","nome":"Arma Secundária grande","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Estilo de Duas Armas. Você pode empunhar duas armas de uma mão com o poder Estilo de Duas Armas."},
  {"id":"arremesso-multiplo","nome":"Arremesso Múltiplo","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Des 13, Estilo de Arremesso. Uma vez por rodada, quando faz um ataque com uma arma de arremesso, você pode gastar 1 PM para fazer um ataque adicional contra o mesmo alvo, arremessando outra arma de arremesso."},
  {"id":"arremesso-potente","nome":"Arremesso Potente","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: For 13, Estilo de Arremesso. Quando usa uma arma de arremesso, você pode usar sua Força em vez de Destreza nos testes de ataque. Se você possuir o poder Ataque Poderoso, poderá usá-lo com armas de arremesso."},
  {"id":"ataque-escudo","nome":"Ataque com Escudo","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Estilo de Arma e Escudo. Uma vez por rodada, se estiver empunhando um escudo e fizer a ação agredir, você pode gastar 1 PM para fazer um ataque corpo a corpo extra com o escudo. Este ataque não faz você perder o bônus do escudo na Defesa."},
  {"id":"ataque-pesado","nome":"Ataque Pesado","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Estilo de Duas Mãos. Quando faz um ataque corpo a corpo com uma arma de duas mãos, você pode pagar 1 PM. Se fizer isso e acertar o ataque, além do dano você faz uma manobra derrubar ou empurrar contra o alvo como uma ação livre (use o resultado do ataque como o teste de manobra)."},
  {"id":"ataque-poderoso","nome":"Ataque Poderoso","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: For 13. Sempre que faz um ataque corpo a corpo, você pode sofrer –2 no teste de ataque para receber +5 na rolagem de dano."},
  {"id":"ataque-preciso","nome":"Ataque Preciso","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Estilo de Uma Arma. Se estiver empunhando uma arma corpo a corpo em uma das mãos e nada na outra, você recebe +2 na margem de ameaça e +1 no multiplicador de crítico com ela."},
  {"id":"bloqueio-escudo","nome":"Bloqueio com Escudo","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Estilo de Arma e Escudo. Quando sofre dano, você pode gastar 1 PM para receber redução de dano igual ao bônus na Defesa que seu escudo fornece contra este dano. Você só pode usar este poder se estiver usando um escudo."},
  {"id":"carga-cavalaria","nome":"Carga de Cavalaria","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Ginete. Quando faz uma investida montada, você causa +2d8 pontos de dano. Além disso, pode continuar se movendo depois do ataque. Você deve se mover em linha reta e seu movimento máximo ainda é o dobro do seu deslocamento."},
  {"id":"combate-defensivo","nome":"Combate Defensivo","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Int 13. Quando usa a ação agredir, você pode usar este poder. Se fizer isso, até seu próximo turno, sofre –2 em todos os testes de ataque, mas recebe +5 na Defesa."},
  {"id":"derrubar-aprimorado","nome":"Derrubar Aprimorado","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Combate Defensivo. Você recebe +2 em testes de ataque para derrubar. Quando derruba uma criatura com essa manobra, pode gastar 1 PM para fazer um ataque extra contra ela."},
  {"id":"desarmar-aprimorado","nome":"Desarmar Aprimorado","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Combate Defensivo. Você recebe +2 em testes de ataque para desarmar. Quando desarma uma criatura, pode gastar 1 PM para arremessar a arma dela para longe. Para definir onde a arma cai, role 1d8 para a direção (sendo “1” diretamente à sua frente, “2” à frente e à direita e assim por diante) e 1d6 para a distância (medida em quadrados de 1,5m a partir da criatura desarmada)."},
  {"id":"disparo-preciso","nome":"Disparo Preciso","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Estilo de Disparo ou Estilo de Arremesso. Você pode fazer ataques à distância contra oponentes envolvidos em combate corpo a corpo sem sofrer a penalidade de –5 no teste de ataque."},
  {"id":"disparo-rapido","nome":"Disparo Rápido","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Des 13, Estilo de Disparo. Se estiver empunhando uma arma de disparo que possa recarregar como ação livre e gastar uma ação completa para agredir, pode fazer um ataque adicional com ela. Se fizer isso, sofre –2 em todos os testes de ataque até o seu próximo turno."},
  {"id":"empunhadura-poderosa","nome":"Empunhadura Poderosa","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: For 17. Ao usar uma arma feita para uma categoria de tamanho maior que a sua, a penalidade que você sofre nos testes de ataque diminui para –2 (normalmente, usar uma arma de uma categoria de tamanho maior impõe –5 nos testes de ataque)."},
  {"id":"encouracado","nome":"Encouraçado","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: proficiência com armaduras pesadas. Se estiver usando uma armadura pesada, você recebe +2 na Defesa. Esse bônus aumenta em +2 para cada outro poder que você possua que tenha Encouraçado como pré-requisito."},
  {"id":"esquiva","nome":"Esquiva","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Des 13. Você recebe +2 na Defesa e Reflexos."},
  {"id":"estilo-arma-escudo","nome":"Estilo de Arma e Escudo","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: treinado em Luta, proficiência com escudos. Se você estiver usando um escudo, o bônus na Defesa que ele fornece aumenta em +2."},
  {"id":"estilo-arma-longa","nome":"Estilo de Arma Longa","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: For 13, treinado em Luta. Você recebe +2 em testes de ataque com armas alongadas e pode atacar alvos adjacentes com essas armas."},
  {"id":"estilo-arremesso","nome":"Estilo de Arremesso","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: treinado em Pontaria. Você pode sacar armas de arremesso como uma ação livre e recebe +2 nas rolagens de dano com elas. Se também possuir o poder Saque Rápido, também recebe +2 nos testes de ataque com essas armas."},
  {"id":"estilo-disparo","nome":"Estilo de Disparo","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: treinado em Pontaria. Se estiver usando uma arma de disparo, você soma sua Destreza nas rolagens de dano."},
  {"id":"estilo-duas-armas","nome":"Estilo de Duas Armas","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Des 15, treinado em Luta. Se estiver empunhando duas armas (e pelo menos uma delas for leve) e fizer a ação agredir, você pode fazer dois ataques, um com cada arma. Se fizer isso, sofre –2 em todos os testes de ataque até o seu próximo turno. Se possuir Ambidestria, em vez disso não sofre penalidade para usá-lo."},
  {"id":"estilo-duas-maos","nome":"Estilo de Duas Mãos","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: For 15, treinado em Luta. Se estiver usando uma arma corpo a corpo com as duas mãos, você recebe +5 nas rolagens de dano. Este poder não pode ser usado com armas leves."},
  {"id":"estilo-uma-arma","nome":"Estilo de Uma Arma","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: treinado em Luta. Se estiver usando uma arma corpo a corpo em uma das mãos e nada na outra, você recebe +2 na Defesa e nos testes de ataque com essa arma (exceto ataques desarmados)."},
  {"id":"estilo-desarmado","nome":"Estilo Desarmado","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: treinado em Luta. Seus ataques desarmados causam 1d6 pontos de dano e podem causar dano letal ou não letal (sem penalidades)."},
  {"id":"fanatico","nome":"Fanático","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: 12º nível de personagem, Encouraçado. Seu deslocamento não é reduzido por usar armaduras pesadas."},
  {"id":"finta-aprimorada","nome":"Finta Aprimorada","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: treinado em Enganação. Você recebe +2 em testes de Enganação para fintar e pode fintar como uma ação de movimento."},
  {"id":"foco-arma","nome":"Foco em Arma","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: proficiência com a arma. Escolha uma arma. Você recebe +2 em testes de ataque com essa arma. Você pode escolher este poder outras vezes para armas diferentes."},
  {"id":"ginete","nome":"Ginete","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: treinado em Cavalgar. Você passa automaticamente em testes de Cavalgar para não cair da montaria quando sofre dano. Além disso, não sofre penalidades para atacar à distância ou lançar magias quando montado."},
  {"id":"inexpugnavel","nome":"Inexpugnável","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Encouraçado, 6º nível de personagem. Se estiver usando uma armadura pesada, você recebe +2 em todos os testes de resistência."},
  {"id":"mira-apurada","nome":"Mira Apurada","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Sab 13, Disparo Preciso. Quando usa a ação mirar, você recebe +2 em testes de ataque e na margem de ameaça com ataques à distância até o fim do turno."},
  {"id":"piqueiro","nome":"Piqueiro","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Estilo de Arma Longa. Uma vez por rodada, se estiver empunhando uma arma alongada e um inimigo entrar voluntariamente em seu alcance corpo a corpo, você pode gastar 1 PM para fazer um ataque corpo a corpo contra este oponente com esta arma. Se o oponente tiver se aproximado fazendo uma investida, seu ataque causa dois dados de dano extra do mesmo tipo."},
  {"id":"presenca-aterradora","nome":"Presença Aterradora","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: treinado em Intimidação. Você pode gastar uma ação padrão e 1 PM para assustar todas as criaturas a sua escolha em alcance curto. Veja a perícia Intimidação para as regras de assustar."},
  {"id":"proficiencia","nome":"Proficiência","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Escolha uma proficiência: armas marciais, armas de fogo, armaduras pesadas ou escudos (se for proficiente em armas marciais, você também pode escolher armas exóticas). Você recebe essa proficiência. Você pode escolher este poder outras vezes para proficiências diferentes."},
  {"id":"quebrar-aprimorado","nome":"Quebrar Aprimorado","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Ataque Poderoso. Você recebe +2 em testes de ataque para quebrar. Quando reduz os PV de uma arma para 0 ou menos, você pode gastar 1 PM para realizar um ataque extra contra o usuário dela. O ataque adicional usa os mesmos valores de ataque e dano, mas os dados devem ser rolados novamente."},
  {"id":"reflexos-combate","nome":"Reflexos de Combate","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Des 13. Você ganha uma ação de movimento extra no seu primeiro turno de cada combate."},
  {"id":"saque-rapido","nome":"Saque Rápido","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: treinado em Iniciativa. Você recebe +2 em Iniciativa e pode sacar ou guardar itens como uma ação livre (em vez de ação de movimento). Além disso, a ação que você gasta para recarregar armas de disparo diminui em uma categoria (ação completa para padrão, padrão para movimento, movimento para livre)."},
  {"id":"trespassar","nome":"Trespassar","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Ataque Poderoso. Quando você faz um ataque corpo a corpo e reduz os pontos de vida do alvo para 0 ou menos, pode gastar 1 PM para fazer um ataque adicional contra outra criatura dentro do seu alcance."},
  {"id":"vitalidade","nome":"Vitalidade","tipo":"Poder de combate","cat":"Poderes de Combate","desc":"Pré-requisito: Con 13. Você recebe +1 PV por nível de personagem e +2 em Fortitude."},
  {"id":"acrobatico","nome":"Acrobático","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: Des 15. Você pode usar sua Destreza em vez de Força em testes de Atletismo. Além disso, terreno difícil não reduz seu deslocamento nem o impede de realizar investidas."},
  {"id":"sabor-destino","nome":"Ao Sabor do Destino","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: 6º nível de personagem. Confiando em suas próprias habilidades (ou em sua própria sorte), você abre mão de usar itens mágicos. Sua autoconfiança fornece diversos benefícios, de acordo com seu nível de personagem e a lista a seguir. Os bônus não são cumulativos (os bônus em atributos e perícias devem ser aplicados num atributo ou perícia diferente a cada vez). Se você utilizar voluntariamente qualquer item mágico (exceto poções), perde o benefício deste poder até o fim da aventura. Você ainda pode lançar magias, receber magias benéficas ou beneficiar-se de itens usados por outros — por exemplo, pode “ir de carona” em um tapete voador, mas não pode você mesmo conduzi-lo. Benefícios por nível de personagem: 6º +2 em uma perícia; 7º +1 na Defesa; 8º +1 nas rolagens de dano; 9º +1 em um atributo; 11º +2 em uma perícia; 12º +2 na Defesa; 13º +2 nas rolagens de dano; 14º +1 em um atributo; 16º +2 em uma perícia; 17º +3 na Defesa; 18º +3 nas rolagens de dano; 19º +1 em um atributo."},
  {"id":"aparencia-inofensiva","nome":"Aparência Inofensiva","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: Car 13. A primeira criatura inteligente (Int –3 ou maior) que atacar você em uma cena deve fazer um teste de Vontade (CD Car). Se falhar, perderá sua ação. Este poder só funciona uma vez por cena; independentemente de a criatura falhar ou não no teste, poderá atacá-lo nas rodadas seguintes."},
  {"id":"atletico","nome":"Atlético","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: For 15. Você recebe +2 em Atletismo e +3m em seu deslocamento."},
  {"id":"atraente","nome":"Atraente","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: Car 13. Você recebe +2 em testes de perícias baseadas em Carisma contra criaturas que possam se sentir fisicamente atraídas por você."},
  {"id":"comandar","nome":"Comandar","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: Car 13. Você pode gastar uma ação de movimento e 1 PM para gritar ordens para seus aliados em alcance médio. Eles recebem +1 em testes de perícia até o fim da cena."},
  {"id":"costas-largas","nome":"Costas Largas","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: Con 13, For 13. Seu limite de carga aumenta em 5 espaços e você pode se beneficiar de um item vestido adicional."},
  {"id":"foco-pericia","nome":"Foco em Perícia","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: treinado na perícia escolhida. Escolha uma perícia. Quando faz um teste dessa perícia, você pode gastar 1 PM para rolar dois dados e usar o melhor resultado. Você pode escolher este poder outras vezes para perícias diferentes. Este poder não pode ser aplicado em Luta e Pontaria (mas veja Foco em Arma)."},
  {"id":"inventario-organizado","nome":"Inventário Organizado","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: Int 13. Você soma sua Inteligência no limite de espaços que pode carregar. Para você, itens muito leves ou pequenos, que normalmente ocupam meio espaço, em vez disso ocupam 1/4 de espaço."},
  {"id":"investigador","nome":"Investigador","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: Int 13. Você recebe +2 em Investigação e soma sua Inteligência em Intuição."},
  {"id":"lobo-solitario","nome":"Lobo Solitário","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Você recebe +1 em testes de perícia e Defesa se estiver sem nenhum aliado em alcance curto. Você não sofre penalidade por usar Cura em si mesmo."},
  {"id":"medicina","nome":"Medicina","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: Sab 13, treinado em Cura. Você pode gastar uma ação completa para fazer um teste de Cura (CD 15) em uma criatura. Se você passar, ela recupera 1d6 PV, mais 1d6 para cada 5 pontos pelos quais o resultado do teste exceder a CD (2d6 com um resultado 20, 3d6 com um resultado 25 e assim por diante). Você só pode usar este poder uma vez por dia numa mesma criatura."},
  {"id":"parceiro","nome":"Parceiro","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: treinado em Adestramento (parceiro animal) ou Diplomacia (parceiro humanoide), 5º nível de personagem. Você possui um parceiro animal ou humanoide que o acompanha em aventuras. Escolha os detalhes dele, como nome, aparência e personalidade. Em termos de jogo, é um parceiro iniciante de um tipo a sua escolha (veja a página 260). O parceiro obedece às suas ordens e se arrisca para ajudá-lo, mas, se for maltratado, pode parar de segui-lo (de acordo com o mestre). Se perder seu parceiro, você recebe outro no início da próxima aventura."},
  {"id":"sentidos-agucados","nome":"Sentidos Aguçados","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: Sab 13, treinado em Percepção. Você recebe +2 em Percepção, não fica desprevenido contra inimigos que não possa perceber e, sempre que erra um ataque devido a camuflagem, pode rolar mais uma vez o dado da chance de falha."},
  {"id":"sortudo","nome":"Sortudo","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Quando faz um teste, você pode gastar 3 PM para rolá-lo novamente."},
  {"id":"surto-heroico","nome":"Surto Heroico","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Uma vez por rodada, você pode gastar 5 PM para realizar uma ação padrão ou de movimento adicional."},
  {"id":"torcida","nome":"Torcida","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: Car 13. Você recebe +2 em testes de perícia e Defesa quando tem a torcida a seu favor. Entenda-se por “torcida” qualquer número de criaturas inteligentes em alcance médio que não esteja realizando nenhuma ação além de torcer por você."},
  {"id":"treinamento-pericia","nome":"Treinamento em Perícia","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Você se torna treinado em uma perícia a sua escolha. Você pode escolher este poder outras vezes para perícias diferentes."},
  {"id":"veneficio","nome":"Venefício","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: treinado em Ofício (alquimista). Quando usa um veneno, você não corre risco de se envenenar acidentalmente. Além disso, a CD para resistir aos seus venenos aumenta em +2."},
  {"id":"vontade-ferro","nome":"Vontade de Ferro","tipo":"Poder de destino","cat":"Poderes de Destino","desc":"Pré-requisito: Sab 13. Você recebe +1 PM para cada dois níveis de personagem e +2 em Vontade."},
  {"id":"celebrar-ritual","nome":"Celebrar Ritual","tipo":"Poder de magia","cat":"Poderes de Magia","desc":"Pré-requisito: treinado em Misticismo ou Religião, 8º nível de personagem. Você pode lançar magias como rituais. Isso dobra seu limite de PM, mas muda a execução para 1 hora (ou o dobro, o que for maior) e exige um gasto de T$ 10 por PM gasto (em incensos, oferendas...). Assim, um arcanista de 8º nível pode lançar uma magia de 16 PM gastando T$ 160. Magias lançadas como rituais não podem ser armazenadas em itens."},
  {"id":"escrever-pergaminho","nome":"Escrever Pergaminho","tipo":"Poder de magia","cat":"Poderes de Magia","desc":"Pré-requisito: habilidade de classe Magias, treinado em Ofício (escriba). Você pode usar a perícia Ofício (escriba) para fabricar pergaminhos com magias que conheça. Veja a página 121 para a regra de fabricar itens e as páginas 333 e 341 para as regras de pergaminhos. De acordo com o mestre, você pode usar objetos similares, como runas, tabuletas de argila etc."},
  {"id":"foco-magia","nome":"Foco em Magia","tipo":"Poder de magia","cat":"Poderes de Magia","desc":"Pré-requisito: lançar magias. Escolha uma magia que possa lançar. Seu custo diminui em –1 PM (cumulativo com outras reduções de custo). Você pode escolher este poder outras vezes para magias diferentes."},
  {"id":"magia-acelerada","nome":"Magia Acelerada","tipo":"Poder de magia (aprimoramento)","cat":"Poderes de Magia","desc":"Pré-requisito: lançar magias de 2º círculo. Muda a execução da magia para ação livre. Você só pode aplicar este aprimoramento em magias com execução de movimento, padrão ou completa e só pode lançar uma magia como ação livre por rodada. Custo: +4 PM."},
  {"id":"magia-ampliada","nome":"Magia Ampliada","tipo":"Poder de magia (aprimoramento)","cat":"Poderes de Magia","desc":"Pré-requisito: lançar magias. Aumenta o alcance da magia em um passo (de curto para médio, de médio para longo) ou dobra a área de efeito da magia. Por exemplo, uma Bola de Fogo ampliada tem seu alcance aumentado para longo ou sua área aumentada para 12m de raio. Custo: +2 PM."},
  {"id":"magia-discreta","nome":"Magia Discreta","tipo":"Poder de magia (aprimoramento)","cat":"Poderes de Magia","desc":"Pré-requisito: lançar magias. Você lança a magia sem gesticular e falar, usando apenas concentração. Isso permite lançar magias com as mãos presas, amordaçado etc. Também permite lançar magias arcanas usando armadura sem teste de Misticismo. Outros personagens só percebem que você lançou uma magia se passarem num teste de Misticismo (CD 20). Custo: +2 PM."},
  {"id":"magia-ilimitada","nome":"Magia Ilimitada","tipo":"Poder de magia","cat":"Poderes de Magia","desc":"Pré-requisito: lançar magias. Você soma seu atributo-chave no limite de PM que pode gastar numa magia. Por exemplo, um arcanista de 5º nível com Int 4 e este poder pode gastar até 9 PM em cada magia."},
  {"id":"preparar-pocao","nome":"Preparar Poção","tipo":"Poder de magia","cat":"Poderes de Magia","desc":"Pré-requisito: habilidade de classe Magias, treinado em Ofício (alquimista). Você pode usar a perícia Ofício (alquimista) para fabricar poções com magias que conheça de 1º e 2º círculos. Veja a página 121 para a regra de fabricar itens e as páginas 333 e 341 para as regras de poções."},
  {"id":"afinidade-tormenta","nome":"Afinidade com a Tormenta","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Aharadak. Você recebe +10 em testes de resistência contra efeitos da Tormenta, de suas criaturas e de devotos de Aharadak. Além disso, seu primeiro poder da Tormenta não conta para perda de Carisma."},
  {"id":"almejar-impossivel","nome":"Almejar o Impossível","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Valkaria ou Thwor. Quando faz um teste de perícia, um resultado de 19 ou mais no dado sempre é um sucesso, não importando o valor a ser alcançado."},
  {"id":"anfibio","nome":"Anfíbio","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto do Oceano. Você pode respirar embaixo d’água e adquire deslocamento de natação igual a seu deslocamento terrestre."},
  {"id":"apostar-trapaceiro","nome":"Apostar com o Trapaceiro","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Hyninn. Quando faz um teste de perícia, você pode gastar 1 PM para apostar com Hyninn. Você e o mestre rolam 1d20, mas o mestre mantém o resultado dele em segredo. Você então escolhe entre usar seu próprio resultado ou o resultado oculto do mestre (neste caso, ele revela o resultado)."},
  {"id":"armas-ambicao","nome":"Armas da Ambição","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Valkaria. Você recebe +1 em testes de ataque e na margem de ameaça com armas nas quais é proficiente."},
  {"id":"arsenal-profundezas","nome":"Arsenal das Profundezas","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto do Oceano. Você recebe +2 nas rolagens de dano com azagaias, lanças e tridentes e seu multiplicador de crítico com essas armas aumenta em +1."},
  {"id":"astucia-serpente","nome":"Astúcia da Serpente","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Sszzaas. Você recebe +2 em Enganação, Furtividade e Intuição."},
  {"id":"ataque-piedoso","nome":"Ataque Piedoso","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Lena ou Thyatis. Você pode usar armas corpo a corpo para causar dano não letal sem sofrer a penalidade de –5 no teste de ataque."},
  {"id":"aura-medo","nome":"Aura de Medo","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Kallyadranoch. Você pode gastar 2 PM para gerar uma aura de medo de 9m de raio e duração até o fim da cena. Todos os inimigos que entrem na aura devem fazer um teste de Vontade (CD Car) ou ficam abalados até o fim da cena. Uma criatura que passe no teste de Vontade fica imune a esta habilidade por um dia."},
  {"id":"aura-paz","nome":"Aura de Paz","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Marah. Você pode gastar 2 PM para gerar uma aura de paz com 9m de raio e duração de uma cena. Qualquer inimigo dentro da aura que tente fazer uma ação hostil contra você deve fazer um teste de Vontade (CD Car). Se falhar, perderá sua ação. Se passar, fica imune a esta habilidade por um dia."},
  {"id":"aura-restauradora","nome":"Aura Restauradora","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Lena. Efeitos de cura usados por você e seus aliados em um raio de 9m recuperam +1 PV por dado."},
  {"id":"bencao-mana","nome":"Bênção do Mana","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Wynna. Você recebe +1 PM a cada nível ímpar."},
  {"id":"caricia-sombria","nome":"Carícia Sombria","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Tenebra. Você pode gastar 1 PM e uma ação padrão para cobrir sua mão com energia negativa e tocar uma criatura em alcance corpo a corpo. A criatura sofre 2d6 pontos de dano de trevas (Fortitude CD Sab reduz à metade) e você recupera PV iguais à metade do dano causado. Você pode aprender Toque Vampírico como uma magia divina. Se fizer isso, o custo dela diminui em –1 PM."},
  {"id":"centelha-magica","nome":"Centelha Mágica","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Wynna. Escolha uma magia arcana ou divina de 1º círculo. Você aprende e pode lançar essa magia."},
  {"id":"compreender-ermos","nome":"Compreender os Ermos","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Allihanna. Você recebe +2 em Sobrevivência e pode usar Sabedoria para Adestramento (em vez de Carisma)."},
  {"id":"conhecimento-enciclopedico","nome":"Conhecimento Enciclopédico","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Tanna-Toh. Você se torna treinado em duas perícias baseadas em Inteligência a sua escolha."},
  {"id":"conjurar-arma","nome":"Conjurar Arma","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Arsenal. Você pode gastar 1 PM para invocar uma arma corpo a corpo ou de arremesso com a qual seja proficiente. A arma surge em sua mão, fornece +1 em testes de ataque e rolagens de dano, é considerada mágica e dura pela cena. Você não pode criar armas de disparo, mas pode criar 20 munições."},
  {"id":"coragem-total","nome":"Coragem Total","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Arsenal, Khalmyr, Lin-Wu ou Valkaria. Você é imune a efeitos de medo, mágicos ou não. Este poder não elimina fobias raciais (como o medo de altura dos minotauros)."},
  {"id":"cura-gentil","nome":"Cura Gentil","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Lena. Você soma seu Carisma aos PV restaurados por seus efeitos mágicos de cura."},
  {"id":"curandeira-perfeita","nome":"Curandeira Perfeita","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Lena. Você sempre pode escolher 10 em testes de Cura. Além disso, não sofre penalidade por usar essa perícia sem uma maleta de medicamentos. Se possuir o item, recebe +2 no teste de Cura (ou +5, se ele for aprimorado)."},
  {"id":"dedo-verde","nome":"Dedo Verde","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Allihanna. Você aprende e pode lançar Controlar Plantas. Caso aprenda novamente essa magia, seu custo diminui em –1 PM."},
  {"id":"descanso-natural","nome":"Descanso Natural","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Allihanna. Para você, dormir ao relento conta como condição de descanso confortável."},
  {"id":"dom-esperanca","nome":"Dom da Esperança","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Marah. Você soma sua Sabedoria em seus PV em vez de Constituição, e se torna imune às condições alquebrado, esmorecido e frustrado."},
  {"id":"dom-imortalidade","nome":"Dom da Imortalidade","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Thyatis, paladino. Você é imortal. Sempre que morre, não importando o motivo, volta à vida após 3d6 dias. Apenas paladinos podem escolher este poder. Um personagem pode ter Dom da Imortalidade ou Dom da Ressurreição, mas não ambos."},
  {"id":"dom-profecia","nome":"Dom da Profecia","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Thyatis. Você pode lançar Augúrio. Caso aprenda novamente essa magia, seu custo diminui em –1 PM. Você também pode gastar 2 PM para receber +2 em um teste."},
  {"id":"dom-ressurreicao","nome":"Dom da Ressurreição","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Thyatis, clérigo. Você pode gastar uma ação completa e todos os PM que possui (mínimo 1 PM) para tocar o corpo de uma criatura morta há menos de um ano e ressuscitá-la. A criatura volta à vida com 1 PV e 0 PM, e perde 1 ponto de Constituição permanentemente. Este poder só pode ser usado uma vez em cada criatura. Apenas clérigos podem escolher este poder. Um personagem pode ter Dom da Imortalidade ou Dom da Ressurreição, mas não ambos."},
  {"id":"dom-verdade","nome":"Dom da Verdade","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Khalmyr. Você pode pagar 2 PM para receber +5 em testes de Intuição, e em testes de Percepção contra Enganação e Furtividade, até o fim da cena."},
  {"id":"escamas-draconicas","nome":"Escamas Dracônicas","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Kallyadranoch. Você recebe +2 na Defesa e em Fortitude."},
  {"id":"escudo-magico","nome":"Escudo Mágico","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Wynna. Quando lança uma magia, você recebe um bônus na Defesa igual ao círculo da magia lançada até o início do seu próximo turno."},
  {"id":"espada-justiceira","nome":"Espada Justiceira","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Khalmyr. Você pode gastar 1 PM para encantar sua espada (ou outra arma corpo a corpo de corte que esteja empunhando). Ela tem seu dano aumentado em um passo até o fim da cena."},
  {"id":"espada-solar","nome":"Espada Solar","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Azgher. Você pode gastar 1 PM para fazer uma arma corpo a corpo de corte que esteja empunhando causar +1d6 de dano por fogo até o fim da cena."},
  {"id":"extase-loucura","nome":"Êxtase da Loucura","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Aharadak ou Nimb. Toda vez que uma ou mais criaturas falham em um teste de Vontade contra uma de suas habilidades mágicas, você recebe 1 PM temporário cumulativo. Você pode ganhar um máximo de PM temporários por cena desta forma igual a sua Sabedoria."},
  {"id":"familiar-ofidico","nome":"Familiar Ofídico","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Sszzaas. Você recebe um familiar cobra (veja a página 38) que não conta em seu limite de parceiros."},
  {"id":"farsa-fingidor","nome":"Farsa do Fingidor","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Hyninn. Você aprende e pode lançar Criar Ilusão. Caso aprenda novamente essa magia, seu custo diminui em –1 PM."},
  {"id":"fe-guerreira","nome":"Fé Guerreira","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Arsenal. Você pode usar Sabedoria para Guerra (em vez de Inteligência). Além disso, em combate, quando vai fazer um teste de perícia, você pode gastar 2 PM para substituí-lo por um teste de Guerra (exceto para testes de ataque)."},
  {"id":"forma-macaco","nome":"Forma de Macaco","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Hyninn. Você pode gastar uma ação completa e 2 PM para se transformar em um macaco. Você adquire tamanho Minúsculo (o que fornece +5 em Furtividade e –5 em testes de manobra) e recebe deslocamento de escalar 9m. Seu equipamento desaparece (e você perde seus benefícios) até você voltar ao normal, mas suas outras estatísticas não são alteradas. A transformação dura indefinidamente, mas termina caso você faça um ataque, lance uma magia ou sofra dano."},
  {"id":"fulgor-solar","nome":"Fulgor Solar","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Azgher. Você recebe redução de frio e trevas 5. Além disso, quando é alvo de um ataque você pode gastar 1 PM para emitir um clarão solar que deixa o atacante ofuscado por uma rodada."},
  {"id":"furia-divina","nome":"Fúria Divina","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Thwor. Você pode gastar 2 PM para invocar uma fúria selvagem, tornando-se temível em combate. Até o fim da cena, você recebe +2 em testes de ataque e rolagens de dano corpo a corpo, mas não pode executar nenhuma ação que exija paciência ou concentração (como usar a perícia Furtividade ou lançar magias). Se usar este poder em conjunto com a habilidade Fúria, ela também dura uma cena (e não termina se você não atacar ou for alvo de uma ação hostil)."},
  {"id":"golpista-divino","nome":"Golpista Divino","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Hyninn. Você recebe +2 em Enganação, Jogatina e Ladinagem."},
  {"id":"habitante-deserto","nome":"Habitante do Deserto","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Azgher. Você recebe redução de fogo 10 e pode pagar 1 PM para criar água pura e potável suficiente para um odre (ou outro recipiente pequeno)."},
  {"id":"inimigo-tenebra","nome":"Inimigo de Tenebra","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Azgher. Seus ataques e habilidades causam +1d6 pontos de dano contra mortos-vivos. Quando você usa um efeito que gera luz, o alcance da iluminação dobra."},
  {"id":"kiai-divino","nome":"Kiai Divino","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Lin-Wu. Uma vez por rodada, quando faz um ataque corpo a corpo, você pode pagar 3 PM. Se acertar o ataque, causa dano máximo, sem necessidade de rolar dados."},
  {"id":"liberdade-divina","nome":"Liberdade Divina","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Valkaria. Você pode gastar 2 PM para receber imunidade a efeitos de movimento por uma rodada."},
  {"id":"manto-penumbra","nome":"Manto da Penumbra","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Tenebra. Você aprende e pode lançar Escuridão. Caso aprenda novamente essa magia, seu custo diminui em –1 PM."},
  {"id":"mente-analitica","nome":"Mente Analítica","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Tanna-Toh. Você recebe +2 em Intuição, Investigação e Vontade."},
  {"id":"mente-vazia","nome":"Mente Vazia","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Lin-Wu. Você recebe +2 em Iniciativa, Percepção e Vontade."},
  {"id":"mestre-mares","nome":"Mestre dos Mares","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto do Oceano. Você pode falar com animais aquáticos (como o efeito da magia Voz Divina) e aprende e pode lançar Acalmar Animal, mas só contra criaturas aquáticas. Caso aprenda novamente essa magia, seu custo diminui em –1 PM."},
  {"id":"olhar-amedrontador","nome":"Olhar Amedrontador","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Megalokk ou Thwor. Você aprende e pode lançar Amedrontar. Caso aprenda novamente essa magia, seu custo diminui em –1 PM."},
  {"id":"palavras-bondade","nome":"Palavras de Bondade","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Marah. Você aprende e pode lançar Enfeitiçar. Caso aprenda novamente essa magia, seu custo diminui em –1 PM."},
  {"id":"percepcao-temporal","nome":"Percepção Temporal","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Aharadak. Você pode gastar 3 PM para somar sua Sabedoria (limitado por seu nível e não cumulativo com efeitos que somam este atributo) a seus ataques, Defesa e testes de Reflexos até o fim da cena."},
  {"id":"pesquisa-abencoada","nome":"Pesquisa Abençoada","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Tanna-Toh. Se passar uma hora pesquisando seus livros e anotações, você pode rolar novamente um teste de perícia baseada em Inteligência ou Sabedoria que tenha feito desde a última cena. Se tiver acesso a mais livros, você recebe um bônus no teste: +2 para uma coleção particular ou biblioteca pequena e +5 para a biblioteca de um templo ou universidade."},
  {"id":"poder-oculto","nome":"Poder Oculto","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Nimb. Você pode gastar uma ação de movimento e 2 PM para invocar a força, a rapidez ou o vigor dos loucos. Role 1d6 para receber +2 em Força (1 ou 2), Destreza (3 ou 4) ou Constituição (5 ou 6) até o fim da cena. Você pode usar este poder várias vezes, mas bônus no mesmo atributo não são cumulativos."},
  {"id":"presas-primordiais","nome":"Presas Primordiais","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Kallyadranoch ou Megalokk. Você pode gastar 1 PM para transformar seus dentes em presas afiadas até o fim da cena. Você recebe uma arma natural de mordida (dano 1d6, crítico x2, perfuração). Uma vez por rodada, quando usa a ação agredir com outra arma, você pode gastar 1 PM para fazer um ataque corpo a corpo extra com a mordida. Se já possuir outro ataque natural de mordida, em vez disso, o dano desse ataque aumenta em dois passos."},
  {"id":"presas-venenosas","nome":"Presas Venenosas","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Sszzaas. Você pode gastar uma ação de movimento e 1 PM para envenenar uma arma corpo a corpo que esteja empunhando. Em caso de acerto, a arma causa perda de 1d12 pontos de vida. A arma permanece envenenada até atingir uma criatura ou até o fim da cena, o que acontecer primeiro."},
  {"id":"rejeicao-divina","nome":"Rejeição Divina","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Aharadak. Você recebe resistência a magia divina +5."},
  {"id":"reparar-injustica","nome":"Reparar Injustiça","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Khalmyr. Uma vez por rodada, quando um oponente em alcance curto acerta um ataque em você ou em um de seus aliados, você pode gastar 2 PM para fazer este oponente repetir o ataque, escolhendo o pior entre os dois resultados."},
  {"id":"sangue-ferro","nome":"Sangue de Ferro","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Arsenal. Você pode pagar 3 PM para receber +2 em rolagens de dano e redução de dano 5 até o fim da cena."},
  {"id":"sangue-ofidico","nome":"Sangue Ofídico","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Sszzaas. Você recebe resistência a veneno +5 e a CD para resistir aos seus venenos aumenta em +2."},
  {"id":"servos-dragao","nome":"Servos do Dragão","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Kallyadranoch. Você pode gastar uma ação completa e 2 PM para invocar 2d4+1 kobolds capangas em espaços desocupados em alcance curto. Você pode gastar uma ação de movimento para fazer os kobolds andarem (eles têm deslocamento 9m) ou uma ação padrão para fazê-los causar dano a criaturas adjacentes (1d6–1 pontos de dano de perfuração cada). Os kobolds têm For –1, Des 1, Defesa 12, 1 PV e falham automaticamente em qualquer teste de resistência ou oposto. Eles desaparecem quando morrem ou no fim da cena. Os kobolds não agem sem receber uma ordem. Usos criativos para capangas fora de combate ficam a critério do mestre."},
  {"id":"sopro-mar","nome":"Sopro do Mar","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Oceano. Você pode gastar uma ação padrão e 1 PM para soprar vento marinho em um cone de 6m. Criaturas na área sofrem 2d6 pontos de dano de frio (Reflexos CD Sab reduz à metade). Você pode aprender Sopro das Uivantes como uma magia divina. Se fizer isso, o custo dela diminui em –1 PM."},
  {"id":"sorte-loucos","nome":"Sorte dos Loucos","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Nimb. Quando faz um teste, você pode pagar 1 PM para rolá-lo novamente (você pode fazer isso mais de uma vez por teste). Se ainda assim falhar, perde 1d6 PM para cada vez que utilizou este poder neste teste."},
  {"id":"talento-artistico","nome":"Talento Artístico","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Marah. Você recebe +2 em Acrobacia, Atuação e Diplomacia."},
  {"id":"teurgista-mistico","nome":"Teurgista Místico","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Wynna, habilidade de classe Magias. Até uma magia de cada círculo que você aprender poderá ser escolhida entre magias divinas (se você for um conjurador arcano) ou entre magias arcanas (se for um conjurador divino)."},
  {"id":"tradicao-lin-wu","nome":"Tradição de Lin-Wu","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Lin-Wu. Você considera a katana uma arma simples e, se for proficiente em armas marciais, recebe +1 na margem de ameaça com ela."},
  {"id":"transmissao-loucura","nome":"Transmissão da Loucura","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Nimb. Você pode lançar Sussurros Insanos (CD Car). Caso aprenda novamente essa magia, seu custo diminui em –1 PM."},
  {"id":"tropas-duyshidakk","nome":"Tropas Duyshidakk","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Thwor. Você pode gastar uma ação completa e 2 PM para invocar 1d4+1 goblinoides capangas em espaços desocupados em alcance curto. Você pode gastar uma ação de movimento para fazer os goblinoides andarem (eles têm deslocamento 9m) ou uma ação padrão para fazê-los causar dano a criaturas adjacentes (1d6+1 pontos de dano de corte cada). Os goblinoides têm For 1, Des 1, Defesa 15, 1 PV e falham automaticamente em qualquer teste de resistência ou oposto. Eles desaparecem quando morrem ou no fim da cena. Os goblinoides não agem sem receber uma ordem. Usos criativos para capangas fora de combate ficam a critério do mestre."},
  {"id":"urro-divino","nome":"Urro Divino","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Megalokk. Quando faz um ataque ou lança uma magia, você pode pagar 1 PM para somar sua Constituição (mínimo +1) à rolagem de dano desse ataque ou magia."},
  {"id":"visao-trevas","nome":"Visão nas Trevas","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Tenebra. Você enxerga perfeitamente no escuro, incluindo em magias de escuridão."},
  {"id":"voz-civilizacao","nome":"Voz da Civilização","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Tanna-Toh. Você está sempre sob efeito de Compreensão."},
  {"id":"voz-natureza","nome":"Voz da Natureza","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Allihanna. Você pode falar com animais (como o efeito da magia Voz Divina) e aprende e pode lançar Acalmar Animal, mas só contra animais. Caso aprenda novamente essa magia, seu custo diminui em –1 PM."},
  {"id":"voz-monstros","nome":"Voz dos Monstros","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Megalokk. Você conhece os idiomas de todos os monstros inteligentes e pode se comunicar livremente com monstros não inteligentes (Int –4 ou menor), como se estivesse sob efeito da magia Voz Divina."},
  {"id":"zumbificar","nome":"Zumbificar","tipo":"Poder concedido","cat":"Poderes Concedidos","desc":"Pré-requisito: devoto de Tenebra. Você pode gastar uma ação completa e 3 PM para reanimar o cadáver de uma criatura Pequena ou Média adjacente por um dia. O cadáver funciona como um parceiro iniciante de um tipo a sua escolha entre combatente, fortão ou guardião. Além disso, quando sofre dano, você pode sacrificar esse parceiro; se fizer isso, você sofre apenas metade do dano, mas o cadáver é destruído."},
  {"id":"anatomia-insana","nome":"Anatomia Insana","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Você tem 25% de chance (resultado “1” em 1d4) de ignorar o dano adicional de um acerto crítico ou ataque furtivo. A chance aumenta em +25% para cada dois outros poderes da Tormenta que você possui."},
  {"id":"antenas","nome":"Antenas","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Você recebe +1 em Iniciativa, Percepção e Vontade. Este bônus aumenta em +1 para cada dois outros poderes da Tormenta que você possui."},
  {"id":"armamento-aberrante","nome":"Armamento Aberrante","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Pré-requisito: outro poder da Tormenta. Você pode gastar uma ação de movimento e 1 PM para produzir uma versão orgânica de qualquer arma corpo a corpo ou de arremesso com a qual seja proficiente — ela brota do seu braço, ombro ou costas como uma planta grotesca e então se desprende. O dano da arma aumenta em um passo para cada dois outros poderes da Tormenta que você possui. A arma dura pela cena, então se desfaz numa poça de gosma."},
  {"id":"articulacoes-flexiveis","nome":"Articulações Flexíveis","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Você recebe +1 em Acrobacia, Furtividade e Reflexos. Este bônus aumenta em +1 para cada dois outros poderes da Tormenta que você possui."},
  {"id":"asas-insetoides","nome":"Asas Insetoides","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Pré-requisito: quatro outros poderes da Tormenta. Você pode gastar 1 PM para receber deslocamento de voo 9m até o fim do seu turno. O deslocamento aumenta em +1,5m para cada outro poder da Tormenta que você possui."},
  {"id":"carapaca","nome":"Carapaça","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Sua pele é recoberta por placas quitinosas. Você recebe +1 na Defesa. Este bônus aumenta em +1 para cada dois outros poderes da Tormenta que você possui."},
  {"id":"corpo-aberrante","nome":"Corpo Aberrante","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Pré-requisito: outro poder da Tormenta. Crostas vermelhas em várias partes de seu corpo tornam seus ataques mais perigosos. Seu dano desarmado aumenta em um passo, mais um passo para cada quatro outros poderes da Tormenta que você possui."},
  {"id":"cuspir-enxame","nome":"Cuspir Enxame","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Você pode gastar uma ação completa e 2 PM para criar um enxame de insetos rubros em um ponto a sua escolha em alcance curto e com duração sustentada. O enxame tem tamanho Médio e pode passar pelo espaço de outras criaturas. Uma vez por rodada, você pode gastar uma ação de movimento para mover o enxame 9m. No final do seu turno, o enxame causa 2d6 pontos de dano de ácido a qualquer criatura no espaço que ele estiver ocupando. Para cada dois outros poderes da Tormenta que possui, você pode gastar +1 PM quando usa este poder para aumentar o dano do enxame em +1d6."},
  {"id":"dentes-afiados","nome":"Dentes Afiados","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Você recebe uma arma natural de mordida (dano 1d4, crítico x2, corte). Uma vez por rodada, quando usa a ação agredir para atacar com outra arma, pode gastar 1 PM para fazer um ataque corpo a corpo extra com a mordida."},
  {"id":"desprezar-realidade","nome":"Desprezar a Realidade","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Pré-requisito: quatro outros poderes da Tormenta. Você pode gastar 2 PM para ficar no limiar da realidade até o início de seu próximo turno. Nesse estado, você ignora terreno difícil e causa 20% de chance de falha em efeitos usados contra você (não apenas ataques). Para cada dois outros poderes de Tormenta que você possuir, essa chance aumenta em 5% (máximo de 50%)."},
  {"id":"empunhadura-rubra","nome":"Empunhadura Rubra","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Você pode gastar 1 PM para cobrir suas mãos com uma carapaça rubra. Até o final da cena, você recebe +1 em Luta. Este bônus aumenta em +1 para cada dois outros poderes da Tormenta que você possui."},
  {"id":"fome-mana","nome":"Fome de Mana","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Quando passa em um teste de resistência para resistir a uma habilidade mágica de um inimigo, você recebe 1 PM temporário cumulativo. Você pode ganhar um máximo de PM temporários por cena desta forma igual ao número de poderes da Tormenta que possui."},
  {"id":"larva-explosiva","nome":"Larva Explosiva","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Pré-requisito: Dentes Afiados. Se uma criatura que tenha sofrido dano de sua mordida nesta cena for reduzida a 0 ou menos PV, ela explode em chuva cáustica, morrendo e causando 4d4 pontos de dano de ácido em criaturas adjacentes. Para cada dois outros poderes da Tormenta que você possui, o dano aumenta em +2d4. Você é imune a esse dano."},
  {"id":"legiao-aberrante","nome":"Legião Aberrante","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Pré-requisito: Anatomia Insana, três outros poderes da Tormenta. Seu corpo se transforma em uma massa de insetos rubros. Você pode atravessar qualquer espaço por onde seja possível passar uma moeda (mas considera esses espaços como terreno difícil) e recebe +1 em testes contra manobras de combate e de resistência contra efeitos que tenham você como alvo (mas não efeitos de área). Este bônus aumenta em +1 para cada dois outros poderes da Tormenta que você possui."},
  {"id":"maos-membranosas","nome":"Mãos Membranosas","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Você recebe +1 em Atletismo, Fortitude e testes de agarrar. Este bônus aumenta em +1 para cada dois outros poderes da Tormenta que você possui."},
  {"id":"membros-estendidos","nome":"Membros Estendidos","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Seus braços e armas naturais são grotescamente mais longos que o normal, o que aumenta seu alcance natural para ataques corpo a corpo em +1,5m. Para cada quatro outros poderes da Tormenta que você possui, esse alcance aumenta em +1,5m."},
  {"id":"membros-extras","nome":"Membros Extras","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Pré-requisito: quatro outros poderes da Tormenta. Você possui duas armas naturais de patas insetoides que saem de suas costas, ombros ou flancos. Uma vez por rodada, quando usa a ação agredir para atacar com outra arma, pode gastar 2 PM para fazer um ataque corpo a corpo extra com cada uma (dano 1d4, crítico x2, corte). Se possuir Ambidestria ou Estilo de Duas Armas, pode empunhar armas leves em suas patas insetoides (mas ainda precisa pagar 2 PM para atacar com elas e sofre a penalidade de –2 em todos os ataques)."},
  {"id":"mente-aberrante","nome":"Mente Aberrante","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Você recebe resistência a efeitos mentais +1. Além disso, sempre que precisa fazer um teste de Vontade para resistir a uma habilidade, a criatura que usou essa habilidade sofre 1d6 pontos de dano psíquico. Para cada dois outros poderes da Tormenta que você possui o bônus em testes de resistência aumenta em +1 e o dano aumenta em +1d6."},
  {"id":"olhos-vermelhos","nome":"Olhos Vermelhos","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Você recebe visão no escuro e +1 em Intimidação. Este bônus aumenta em +1 para cada dois outros poderes da Tormenta que você possui."},
  {"id":"pele-corrompida","nome":"Pele Corrompida","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Sua carne foi mesclada à matéria vermelha. Você recebe redução de ácido, eletricidade, fogo, frio, luz e trevas 2. Esta RD aumenta em +2 para cada dois outros poderes da Tormenta que você possui."},
  {"id":"sangue-acido","nome":"Sangue Ácido","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Quando você sofre dano por um ataque corpo a corpo, o atacante sofre 1 ponto de dano de ácido por poder da Tormenta que você possui."},
  {"id":"visco-rubro","nome":"Visco Rubro","tipo":"Poder da Tormenta","cat":"Poderes da Tormenta","desc":"Você pode gastar 1 PM para expelir um líquido grosso e corrosivo. Até o final da cena, você recebe +1 nas rolagens de dano corpo a corpo. Este bônus aumenta em +1 para cada dois outros poderes da Tormenta que você possui."},
  {"id":"versatil","nome":"Versátil","tipo":"Habilidade de raça","cat":"Humano","de":"Humano","fonteDe":"raca","desc":"Você se torna treinado em duas perícias a sua escolha (não precisam ser da sua classe). Você pode trocar uma dessas perícias por um poder geral a sua escolha."},
  {"id":"deformidade","nome":"Deformidade","tipo":"Habilidade de raça","cat":"Lefou","de":"Lefou","fonteDe":"raca","desc":"Todo lefou possui defeitos físicos que, embora desagradáveis, conferem certas vantagens. Você recebe +2 em duas perícias a sua escolha. Cada um desses bônus conta como um poder da Tormenta (exceto para perda de Carisma). Você pode trocar um desses bônus por um poder da Tormenta a sua escolha (ele também não conta para perda de Carisma)."},
  {"id":"resistencia-elemental","nome":"Resistência Elemental","tipo":"Habilidade de raça","cat":"Qareen","de":"Qareen","fonteDe":"raca","desc":"Conforme sua ascendência, você recebe redução 10 a um tipo de dano. Escolha uma: frio (qareen da água), eletricidade (do ar), fogo (do fogo), ácido (da terra), luz (da luz) ou trevas (qareen das trevas)."},
  {"id":"tatuagem-mistica","nome":"Tatuagem Mística","tipo":"Habilidade de raça","cat":"Qareen","de":"Qareen","fonteDe":"raca","desc":"Você pode lançar uma magia de 1º círculo a sua escolha (atributo-chave Carisma). Caso aprenda novamente essa magia, seu custo diminui em –1 PM."},
  {"id":"fonte-elemental","nome":"Fonte Elemental","tipo":"Habilidade de raça","cat":"Golem","de":"Golem","fonteDe":"raca","desc":"Você possui um espírito elemental preso em seu corpo. Escolha entre água (frio), ar (eletricidade), fogo (fogo) e terra (ácido). Você é imune a dano desse tipo. Se fosse sofrer dano mágico desse tipo, em vez disso cura PV em quantidade igual à metade do dano. Por exemplo, se um golem com espírito elemental do fogo é atingido por uma Bola de Fogo que causa 30 pontos de dano, em vez de sofrer esse dano, ele recupera 15 PV."},
  {"id":"proposito-criacao","nome":"Propósito de Criação","tipo":"Habilidade de raça","cat":"Golem","de":"Golem","fonteDe":"raca","desc":"Você foi construído “pronto” para um propósito específico e não teve uma infância. Você não tem direito a escolher uma origem, mas recebe um poder geral a sua escolha."},
  {"id":"hibrido","nome":"Híbrido","tipo":"Habilidade de raça","cat":"Kliren","de":"Kliren","fonteDe":"raca","desc":"Sua natureza multifacetada fez com que você aprendesse conhecimentos variados. Você se torna treinado em uma perícia a sua escolha (não precisa ser da sua classe)."},
  {"id":"memoria-postuma","nome":"Memória Póstuma","tipo":"Habilidade de raça","cat":"Osteon","de":"Osteon","fonteDe":"raca","desc":"Você se torna treinado em uma perícia (não precisa ser da sua classe) ou recebe um poder geral a sua escolha. Como alternativa, você pode ser um osteon de outra raça humanoide que não humano. Neste caso, você ganha uma habilidade dessa raça a sua escolha. Se a raça era de tamanho diferente de Médio, você também possui sua categoria de tamanho."},
  {"id":"cancao-mares","nome":"Canção dos Mares","tipo":"Habilidade de raça","cat":"Sereia/Tritão","de":"Sereia/Tritão","fonteDe":"raca","desc":"Você pode lançar duas das magias a seguir: Amedrontar, Comando, Despedaçar, Enfeitiçar, Hipnotismo ou Sono (atributo-chave Carisma). Caso aprenda novamente uma dessas magias, seu custo diminui em –1 PM."},
  {"id":"magia-fadas","nome":"Magia das Fadas","tipo":"Habilidade de raça","cat":"Sílfide","de":"Sílfide","fonteDe":"raca","desc":"Você pode lançar duas das magias a seguir (atributo-chave Carisma): Criar Ilusão, Enfeitiçar, Luz (como uma magia arcana) e Sono. Caso aprenda novamente uma dessas magias, seu custo diminui em –1 PM."},
  {"id":"luz-sagrada-aggelus","nome":"Luz Sagrada (Aggelus)","tipo":"Habilidade de raça","cat":"Suraggel","de":"Suraggel","fonteDe":"raca","desc":"Você recebe +2 em Diplomacia e Intuição. Além disso, pode lançar Luz (como uma magia divina; atributo-chave Carisma). Caso aprenda novamente essa magia, seu custo diminui em –1 PM."},
  {"id":"sombras-profanas-sulfure","nome":"Sombras Profanas (Sulfure)","tipo":"Habilidade de raça","cat":"Suraggel","de":"Suraggel","fonteDe":"raca","desc":"Você recebe +2 em Enganação e Furtividade. Além disso, pode lançar Escuridão (como uma magia divina; atributo-chave Inteligência). Caso aprenda novamente essa magia, seu custo diminui em –1 PM."},
  {"id":"arcanista-arcano-batalha","nome":"Arcano de Batalha","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Quando lança uma magia, você soma seu atributo-chave na rolagem de dano."},
  {"id":"arcanista-aumento-atributo","nome":"Aumento de Atributo","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo."},
  {"id":"arcanista-caldeirao-bruxo","nome":"Caldeirão do Bruxo","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Pré-requisito: Bruxo, treinado em Ofício (alquimista). Você pode criar poções, como se tivesse o poder geral Preparar Poção. Se tiver ambos, pode criar poções de até 5º círculo."},
  {"id":"arcanista-caminho-arcanista","nome":"Caminho do Arcanista","tipo":"Habilidade de classe","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"A magia é um poder incrível, capaz de alterar a realidade. Esse poder tem fontes distintas e cada uma opera conforme suas próprias regras. Escolha uma das opções a seguir: Bruxo, Feiticeiro ou Mago (cada uma está listada como uma habilidade própria). Uma vez feita, essa escolha não pode ser mudada."},
  {"id":"arcanista-caminho-arcanista-bruxo","nome":"Caminho do Arcanista: Bruxo","tipo":"Habilidade de classe","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Você lança magias através de um foco — uma varinha, cajado, chapéu... Para lançar uma magia, você precisa empunhar o foco com uma mão (e gesticular com a outra) ou fazer um teste de Misticismo (CD 20 + o custo em PM da magia; se falhar, a magia não funciona, mas você gasta os PM mesmo assim). O foco tem RD 10 e PV iguais à metade dos seus, independentemente de seu material ou forma. Se for danificado, é totalmente restaurado na próxima vez que você recuperar seus PM por descanso. Se for destruído (reduzido a 0 PV), você fica atordoado por uma rodada. Você pode recuperar um foco destruído ou perdido com uma semana de trabalho e T$ 100. Seu atributo-chave para magias é Inteligência."},
  {"id":"arcanista-caminho-arcanista-feiticeiro","nome":"Caminho do Arcanista: Feiticeiro","tipo":"Habilidade de classe","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Você lança magias através de um poder inato que corre em seu sangue. Escolha uma linhagem como origem de seus poderes (veja a página 39). Você recebe a herança básica da linhagem escolhida. Você não depende de nenhum item ou estudo, mas sua capacidade de aprender magias é limitada — você aprende uma magia nova a cada nível ímpar (3º, 5º, 7º etc.), em vez de a cada nível. Seu atributo-chave para magias é Carisma."},
  {"id":"arcanista-caminho-arcanista-mago","nome":"Caminho do Arcanista: Mago","tipo":"Habilidade de classe","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Você lança magias através de estudo e memorização de fórmulas arcanas. Você só pode lançar magias memorizadas; suas outras magias não podem ser lançadas, mesmo que você tenha pontos de mana para tal. Para memorizar magias, você precisa estudar seu grimório por uma hora. Quando faz isso, escolhe metade das magias que conhece (por exemplo, se conhece 7 magias, escolhe 3). Essas serão suas magias memorizadas. Você pode memorizar magias uma vez por dia. Caso não possa estudar (por não ter tempo, por ter perdido o grimório...), não poderá trocar suas magias memorizadas. Um grimório tem as mesmas estatísticas de um foco (veja acima) e pode ser recuperado da mesma forma. Você começa com uma magia adicional (para um total de 4) e, sempre que ganha acesso a um novo círculo de magias, aprende uma magia adicional daquele círculo. Seu atributo-chave para magias é Inteligência."},
  {"id":"arcanista-conhecimento-magico","nome":"Conhecimento Mágico","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Você aprende duas magias de qualquer círculo que possa lançar. Você pode escolher este poder quantas vezes quiser."},
  {"id":"arcanista-contramagica-aprimorada","nome":"Contramágica Aprimorada","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Pré-requisito: Dissipar Magia. Uma vez por rodada, você pode fazer uma contramágica como uma reação (veja a página 173)."},
  {"id":"arcanista-envolto-misterio","nome":"Envolto em Mistério","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Sua aparência e postura assombrosas o permitem manipular e assustar pessoas ignorantes ou supersticiosas. O mestre define o que exatamente você pode fazer e quem se encaixa nessa descrição. Como regra geral, você recebe +5 em Enganação e Intimidação contra pessoas não treinadas em Conhecimento ou Misticismo."},
  {"id":"arcanista-escriba-arcano","nome":"Escriba Arcano","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Pré-requisito: Mago, treinado em Ofício (escriba). Você pode aprender magias copiando os textos de pergaminhos e grimórios de outros magos. Aprender uma magia dessa forma exige um dia de trabalho e T$ 250 em matérias-primas por PM necessário para lançar a magia. Assim, aprender uma magia de 3º círculo (6 PM) exige 6 dias de trabalho e o gasto de T$ 1.500."},
  {"id":"arcanista-especialista-escola","nome":"Especialista em Escola","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Pré-requisito: Bruxo ou Mago. Escolha uma escola de magia. A CD para resistir a suas magias dessa escola aumenta em +2."},
  {"id":"arcanista-familiar","nome":"Familiar","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Você possui um animal de estimação mágico. Veja o quadro para detalhes. Familiares Arcanos Um familiar é uma criatura mágica. Em termos de jogo, é um parceiro especial com o qual você pode se comunicar telepaticamente em alcance longo. Ele obedece a suas ordens, mas ainda está limitado ao que uma criatura de sua espécie pode fazer. Se ele morrer, você fica atordoado por uma rodada. Você pode invocar um novo familiar com um ritual que exige um dia e T$ 100 em ingredientes. Borboleta. A CD dos testes de Vontade para resistir a suas magias aumenta em +1. Cobra. A CD dos testes de Fortitude para resistir a suas magias aumenta em +1. Coruja. Quando lança uma magia com alcance de toque, você pode pagar 1 PM para aumentar seu alcance para curto. Corvo. Quando faz um teste de Misticismo ou Vontade, você pode pagar 1 PM para rolar dois dados e usar o melhor resultado. Falcão. Você não pode ser surpreendido e nunca fica desprevenido. Gato. Você recebe visão no escuro e +2 em Furtividade. Lagarto. A CD dos testes de Reflexos para resistir a suas magias aumenta em +1. Morcego. Você adquire percepção às cegas em alcance curto. Rato. Você pode usar seu atributo-chave em Fortitude, no lugar de Constituição. Sapo. Você soma seu atributo-chave ao seu total de pontos de vida (cumulativo)."},
  {"id":"arcanista-fluxo-mana","nome":"Fluxo de Mana","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Pré-requisito: 10º nível de arcanista. Você pode manter dois efeitos sustentados ativos simultaneamente com apenas uma ação livre, pagando o custo de cada efeito separadamente."},
  {"id":"arcanista-foco-vital","nome":"Foco Vital","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Pré-requisito: Bruxo. Se você estiver segurando seu foco e sofrer dano que o levaria a 0 PV ou menos, você fica com 1 PV e o foco perde PV igual ao valor excedente ou até ser destruído (se o foco for destruído, você sofre o dano excedente)."},
  {"id":"arcanista-fortalecimento-arcano","nome":"Fortalecimento Arcano","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Pré-requisito: 5º nível de arcanista. A CD para resistir a suas magias aumenta em +1. Se você puder lançar magias de 4º círculo, em vez disso ela aumenta em +2."},
  {"id":"arcanista-heranca-aprimorada","nome":"Herança Aprimorada","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Pré-requisito: Feiticeiro, 6º nível de arcanista. Você recebe a herança aprimorada de sua linhagem sobrenatural."},
  {"id":"arcanista-heranca-superior","nome":"Herança Superior","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Pré-requisito: Herança Aprimorada, 11º nível de arcanista. Você recebe a herança superior de sua linhagem sobrenatural."},
  {"id":"arcanista-linhagem-draconica","nome":"Linhagem Dracônica","tipo":"Habilidade de classe","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Um de seus antepassados foi um majestoso dragão. Escolha um tipo de dano entre ácido, eletricidade, fogo ou frio. Básica. Você soma seu Carisma em seus pontos de vida iniciais e recebe redução de dano 5 ao tipo escolhido. Aprimorada. Suas magias do tipo escolhido custam –1 PM e causam +1 ponto de dano por dado. Superior. Você passa a somar o dobro do seu Carisma em seus pontos de vida iniciais e se torna imune a dano do tipo escolhido. Além disso, sempre que reduz um ou mais inimigos a 0 PV ou menos com uma magia do tipo escolhido, você recebe uma quantidade de PM temporários igual ao círculo da magia."},
  {"id":"arcanista-linhagem-feerica","nome":"Linhagem Feérica","tipo":"Habilidade de classe","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Seu sangue foi tocado pelas fadas. Básica. Você se torna treinado em Enganação e aprende uma magia de 1º círculo de encantamento ou ilusão, arcana ou divina, a sua escolha. Aprimorada. A CD para resistir a suas magias de encantamento e ilusão aumenta em +2 e suas magias dessas escolas custam –1 PM. Superior. Você recebe +2 em Carisma. Se uma criatura passar no teste de resistência contra uma magia de encantamento ou ilusão lançada por você, você fica alquebrado até o final da cena."},
  {"id":"arcanista-linhagem-rubra","nome":"Linhagem Rubra","tipo":"Habilidade de classe","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Seu sangue foi corrompido pela Tormenta. Básica. Você recebe um poder da Tormenta. Além disso, pode perder outro atributo em vez de Carisma por poderes da Tormenta. Aprimorada. Escolha uma magia para cada poder da Tormenta que você possui. Essas magias custam –1 PM. Sempre que recebe um novo poder da Tormenta, você pode escolher uma nova magia. Esta herança conta como um poder da Tormenta (exceto para perda de Carisma). Superior. Você recebe +4 PM para cada poder da Tormenta que tiver. Esta herança conta como um poder da Tormenta (exceto para perda de Carisma)."},
  {"id":"arcanista-magia-pungente","nome":"Magia Pungente","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Quando lança uma magia, você pode pagar 1 PM para aumentar em +2 a CD para resistir a ela."},
  {"id":"arcanista-mestre-escola","nome":"Mestre em Escola","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Pré-requisito: Especialista em Escola com a escola escolhida, 8º nível de arcanista. Escolha uma escola de magia. O custo para lançar magias dessa escola diminui em –1 PM."},
  {"id":"arcanista-poder-magico","nome":"Poder Mágico","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Você recebe +1 ponto de mana por nível de arcanista. Quando sobe de nível, os PM que recebe por este poder aumentam de acordo. Por exemplo, se escolher este poder no 4º nível, recebe 4 PM. Quando subir para o 5º nível, recebe +1 PM e assim por diante."},
  {"id":"arcanista-raio-arcano","nome":"Raio Arcano","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Você pode gastar uma ação padrão para causar 1d8 pontos de dano de essência num alvo em alcance curto. Esse dano aumenta em +1d8 para cada círculo de magia acima do 1º que você puder lançar. O alvo pode fazer um teste de Reflexos (CD atributo-chave) para reduzir o dano à metade. O raio arcano conta como uma magia para efeitos de habilidades e itens que beneficiem suas magias."},
  {"id":"arcanista-raio-elemental","nome":"Raio Elemental","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Pré-requisito: Raio Arcano. Quando usa Raio Arcano, você pode pagar 1 PM para que ele cause dano de ácido, eletricidade, fogo, frio ou trevas, a sua escolha. Se o alvo falhar no teste de Reflexos, sofre uma condição, de acordo com o tipo de dano (veja a descrição das condições na página 394). Ácido: vulnerável por 1 rodada. Eletricidade: ofuscado por 1 rodada. Fogo: fica em chamas. Frio: lento por 1 rodada. Trevas: não pode curar PV por 1 rodada."},
  {"id":"arcanista-raio-poderoso","nome":"Raio Poderoso","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Pré-requisito: Raio Arcano. Os dados de dano do seu Raio Arcano aumentam para d12 e o alcance dele aumenta para médio."},
  {"id":"arcanista-tinta-mago","nome":"Tinta do Mago","tipo":"Poder de arcanista","cat":"Arcanista","de":"Arcanista","fonteDe":"classe","desc":"Pré-requisito: Mago, treinado em Ofício (escriba). Você pode criar pergaminhos, como se tivesse o poder Escrever Pergaminho. Se tiver ambos, seu custo para criar pergaminhos é reduzido à metade."},
  {"id":"barbaro-alma-bronze","nome":"Alma de Bronze","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Quando entra em fúria, você recebe uma quantidade de pontos de vida temporários igual a seu nível + sua Força."},
  {"id":"barbaro-aumento-atributo","nome":"Aumento de Atributo","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo."},
  {"id":"barbaro-brado-assustador","nome":"Brado Assustador","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Pré-requisito: treinado em Intimidação. Você pode gastar uma ação de movimento e 1 PM para soltar um berro feroz. Todos os inimigos em alcance curto ficam vulneráveis até o fim da cena. Medo."},
  {"id":"barbaro-critico-brutal","nome":"Crítico Brutal","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Pré-requisito: 6º nível de bárbaro. Seu multiplicador de crítico com armas corpo a corpo e de arremesso aumenta em +1. Por exemplo, seu multiplicador com um machado de batalha (normalmente x3) será x4."},
  {"id":"barbaro-destruidor","nome":"Destruidor","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Pré-requisito: For 13. Quando causa dano com uma arma corpo a corpo de duas mãos, você pode rolar novamente qualquer resultado 1 ou 2 das rolagens de dano da arma."},
  {"id":"barbaro-espirito-inquebravel","nome":"Espírito Inquebrável","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Pré-requisito: Alma de Bronze. Enquanto está em fúria, você não fica inconsciente por estar com 0 PV ou menos (você ainda morre se chegar em um valor negativo igual à metade de seus pontos de vida máximos)."},
  {"id":"barbaro-esquiva-sobrenatural","nome":"Esquiva Sobrenatural","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Seus instintos são tão apurados que você consegue reagir ao perigo antes que seus sentidos o percebam. Você nunca fica surpreendido."},
  {"id":"barbaro-forca-indomavel","nome":"Força Indomável","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Quando faz um teste de Força ou Atletismo, você pode gastar 1 PM para somar seu nível nele. Você pode usar esta habilidade depois de rolar o dado, mas deve usá-la antes de o mestre dizer se você passou ou não."},
  {"id":"barbaro-frenesi","nome":"Frenesi","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Uma vez por rodada, se estiver em fúria e usar a ação agredir para fazer um ataque corpo a corpo ou com uma arma de arremesso, você pode gastar 2 PM para fazer um ataque adicional."},
  {"id":"barbaro-furia-savana","nome":"Fúria da Savana","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Seu deslocamento aumenta em +3m. Quando usa Fúria, você aplica o bônus em ataque e dano também a armas de arremesso."},
  {"id":"barbaro-furia-raivosa","nome":"Fúria Raivosa","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Se sua Fúria for terminar por você não ter atacado nem sido alvo de um efeito hostil, você pode pagar 1 PM para continuar em fúria nesta rodada. Se você atacar ou for atacado na rodada seguinte, sua fúria continua normalmente."},
  {"id":"barbaro-golpe-poderoso","nome":"Golpe Poderoso","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Ao acertar um ataque corpo a corpo ou com uma arma de arremesso, você pode gastar 1 PM para causar um dado extra de dano do mesmo tipo (por exemplo, com um montante, causa +1d6, para um dano total de 3d6; com um machado de guerra, causa +1d12, para um dano total de 2d12)."},
  {"id":"barbaro-impeto","nome":"Ímpeto","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Você pode gastar 1 PM para aumentar seu deslocamento em +6m por uma rodada."},
  {"id":"barbaro-investida-imprudente","nome":"Investida Imprudente","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Quando faz uma investida, você pode aumentar sua penalidade na Defesa pela investida para –5 para receber um bônus de +1d12 na rolagem de dano deste ataque."},
  {"id":"barbaro-pele-aco","nome":"Pele de Aço","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Pré-requisito: Pele de Ferro, 8º nível de bárbaro. O bônus de Pele de Ferro aumenta para +8."},
  {"id":"barbaro-pele-ferro","nome":"Pele de Ferro","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Você recebe +4 na Defesa, mas apenas se não estiver usando armadura pesada."},
  {"id":"barbaro-sangue-inimigos","nome":"Sangue dos Inimigos","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Enquanto está em fúria, quando faz um acerto crítico ou reduz um inimigo a 0 PV, você recebe um bônus cumulativo de +1 em testes de ataque e rolagens de dano, limitado pelo seu nível, até o fim da cena."},
  {"id":"barbaro-supersticao","nome":"Superstição","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Você odeia magia, o que faz com que seja mais resistente a ela. Você recebe resistência a magia +5."},
  {"id":"barbaro-totem-espiritual","nome":"Totem Espiritual","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Pré-requisito: Sab 13, 4º nível de bárbaro. Você soma sua Sabedoria no seu total de pontos de mana. Escolha um animal totêmico (veja o quadro ao lado). Você aprende e pode lançar uma magia definida pelo animal esco - lhido (atributo-chave Sabedoria) e pode lançá-la mesmo em fúria. Animais Totêmicos A seguir está uma lista de animais venerados por tribos bárbaras de Arton. Coruja. A sábia coruja guia seus discípulos. Você pode lançar Orientação. Corvo. Um seguidor do corvo enxerga além do véu. Você pode lançar Visão Mística. Falcão. Sempre atento, o falcão permite que você lance Detectar Ameaças. Grifo. O mais veloz dos animais, o grifo permite que você lance Primor Atlético. Lobo. O lobo é feroz e letal. Você pode lançar Concentração de Combate. Raposa. A sagaz raposa nunca está onde se espera. Você pode lançar Imagem Espelhada. Tartaruga. A tartaruga protege os seus. Você pode lançar Armadura Arcana. Urso. O vigoroso urso permite que você lance Vitalidade Fantasma e possa usar seus aprimoramentos como se tivesse acesso aos mesmos círculos de magia que um druida de seu nível."},
  {"id":"barbaro-vigor-primal","nome":"Vigor Primal","tipo":"Poder de bárbaro","cat":"Bárbaro","de":"Bárbaro","fonteDe":"classe","desc":"Você pode gastar uma ação de movimento e uma quantidade de PM limitada por sua Constituição. Para cada PM que gastar, você recupera 1d12 pontos de vida."},
  {"id":"bardo-arte-magica","nome":"Arte Mágica","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Enquanto você estiver sob efeito de sua Inspiração, a CD para resistir a suas habilidades de bardo aumenta em +2."},
  {"id":"bardo-aumentar-repertorio","nome":"Aumentar Repertório","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Você aprende duas magias de qualquer círculo que possa lançar. Elas devem pertencer às escolas que você sabe usar, mas podem ser arcanas ou divinas. Você pode escolher este poder quantas vezes quiser."},
  {"id":"bardo-aumento-atributo","nome":"Aumento de Atributo","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo."},
  {"id":"bardo-danca-laminas","nome":"Dança das Lâminas","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Pré-requisito: Esgrima Mágica, 10º nível de bardo. Quando você lança uma magia com execução de uma ação padrão, pode gastar 1 PM para fazer um ataque corpo a corpo como uma ação livre."},
  {"id":"bardo-esgrima-magica","nome":"Esgrima Mágica","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Sua arte mescla esgrima e magia, transformando dança em golpes. Se estiver sob efeito de Inspiração, você pode substituir testes de Luta por testes de Atuação, mas apenas para ataques com armas corpo a corpo leves ou de uma mão."},
  {"id":"bardo-estrelato","nome":"Estrelato","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Pré-requisito: 6º nível de bardo. Suas apresentações o tornaram famoso, fazendo com que você seja reconhecido e bem tratado por aqueles que apreciam a arte. Por outro lado, pode ser difícil passar despercebido, especialmente em grandes cidades. Quando usa Atuação para impressionar uma plateia, o bônus recebido em perícias baseadas em Carisma aumenta para +5."},
  {"id":"bardo-fascinar-massa","nome":"Fascinar em Massa","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Pré-requisito: Música: Balada Fascinante. Quando usa Música: Balada Fascinante, você pode gastar +2 PM. Se fizer isso, afeta todas as criaturas a sua escolha no alcance da música (você faz um único teste de Atuação, oposto pelo teste de Vontade de cada criatura)."},
  {"id":"bardo-golpe-elemental","nome":"Golpe Elemental","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Pré-requisito: Golpe Mágico. Enquanto estiver sob efeito de Inspiração, sempre que você acertar um ataque corpo a corpo, pode gastar 1 PM para causar 1d6 de dano extra de ácido, eletricidade, fogo ou frio, a sua escolha. Para cada quatro níveis que possuir, pode gastar +1 PM para aumentar o dano em +1d6."},
  {"id":"bardo-golpe-magico","nome":"Golpe Mágico","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Pré-requisito: Esgrima Mágica. Enquanto estiver sob efeito de Inspiração, sempre que você acertar um ataque corpo a corpo em um inimigo, recebe 2 PM temporários cumulativos. Você pode ganhar um máximo de PM temporários por cena igual ao seu nível. Esses pontos temporários desaparecem no final da cena."},
  {"id":"bardo-inspiracao-marcial","nome":"Inspiração Marcial","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Quando você usa Inspiração, você e seus aliados aplicam o bônus recebido em rolagens de dano (além de testes de perícia)."},
  {"id":"bardo-lendas-historias","nome":"Lendas e Histórias","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Pré-requisito: Int 13. Você é um arquivo vivo de relatos, canções e folclore. Além de outros benefícios a critério do mestre, quando faz um teste de Conhecimento, Misticismo, Nobreza ou Religião para informação, identificar criaturas ou identificar itens mágicos, você pode gastar 1 PM para rolá-lo novamente."},
  {"id":"bardo-manipular","nome":"Manipular","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Pré-requisito: Música: Balada Fascinante. Você pode gastar 1 PM para fazer uma criatura fascinada por você ficar enfeitiçada até o fim da cena (Von CD Car anula). Se a criatura passar, fica imune a este efeito por um dia. Usar esta habilidade não conta como ameaça à criatura fascinada."},
  {"id":"bardo-manipular-massa","nome":"Manipular em Massa","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Pré-requisito: Fascinar em Massa, Manipular, 10º nível de bardo. Quando usa Manipular, você pode gastar +2 PM. Se fizer isso, afeta todas as criaturas a sua escolha em alcance curto."},
  {"id":"bardo-melodia-restauradora","nome":"Melodia Restauradora","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Pré-requisito: Música: Melodia Curativa. Quando você usa Música: Melodia Curativa, pode gastar +2 PM. Se fizer isso, escolha uma das condições a seguir: abalado, alquebrado, apavorado, atordoado, cego, confuso, enfeitiçado, esmorecido, exausto, fatigado, frustrado, pasmo ou surdo. Você remove a condição escolhida das criaturas afetadas pela música."},
  {"id":"bardo-mestre-sussurros","nome":"Mestre dos Sussurros","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Pré-requisito: Car 13, treinado em Enganação e Investigação. Você é dissimulado, atento para rumores e ótimo em espalhar fofocas. Quando faz um teste de Investigação para interrogar ou um teste de Enganação para intriga, você rola dois dados e usa o melhor resultado. Além disso, pode fazer esses testes em ambientes sociais (taverna, festival, corte...) sem custo e em apenas um minuto."},
  {"id":"bardo-musica-balada-fascinante","nome":"Música: Balada Fascinante","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Faça um teste de Atuação oposto pelo teste de Vontade de uma criatura no alcance. Se você passar, ela fica fascinada enquanto você se concentrar (uma ação padrão por rodada). Um alvo hostil ou envolvido em combate recebe +5 no teste de resistência e tem direito a um novo teste sempre que você se concentrar. Se a criatura passar, fica imune a este efeito por um dia."},
  {"id":"bardo-musica-cancao-assustadora","nome":"Música: Canção Assustadora","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Faça um teste de Atuação oposto pelo teste de Vontade de cada criatura a sua escolha dentro do alcance (você faz um único teste). Alvos que falhem ficam abalados até o fim da cena. Alvos que passem ficam imunes a este efeito por um dia."},
  {"id":"bardo-musica-melodia-curativa","nome":"Música: Melodia Curativa","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Criaturas a sua escolha no alcance recuperam 1d6 PV. Quando usa esta habilidade, você pode gastar mais pontos de mana. Para cada PM extra, aumente a cura em +1d6 PV."},
  {"id":"bardo-parodia","nome":"Paródia","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Uma vez por rodada, quando vê outra criatura lançando uma magia em alcance médio, você pode pagar 1 PM e fazer um teste de Atuação (CD 15 + custo em PM da magia). Se passar, até o final de seu próximo turno você pode lançar essa magia."},
  {"id":"bardo-prestidigitacao","nome":"Prestidigitação","tipo":"Poder de bardo","cat":"Bardo","de":"Bardo","fonteDe":"classe","desc":"Pré-requisito: 6º nível de bardo. Quando faz uma ação padrão, você pode aproveitar seus gestos para lançar uma magia com execução de ação completa ou menor. Faça um teste de Atuação (CD 15 + custo em PM da magia). Se passar, você lança a magia como uma ação livre. Se falhar, a magia não funciona, mas você gasta os PM mesmo assim. Outros personagens só percebem que você lançou uma magia com um teste de Misticismo (CD 20)."},
  {"id":"bucaneiro-abusar-fracos","nome":"Abusar dos Fracos","tipo":"Poder de bucaneiro","cat":"Bucaneiro","de":"Bucaneiro","fonteDe":"classe","desc":"Pré-requisito: Flagelo dos Mares. Quando ataca uma criatura sob efeito de uma condição de medo, seu dano aumenta em um passo."},
  {"id":"bucaneiro-amigos-porto","nome":"Amigos no Porto","tipo":"Poder de bucaneiro","cat":"Bucaneiro","de":"Bucaneiro","fonteDe":"classe","desc":"Pré-requisito: Car 13, 6º nível de bucaneiro. Quando chega em uma comunidade portuária, você pode fazer um teste de Carisma (CD 10). Se passar, encontra um amigo para o qual pode pedir um favor ou que pode ajudá-lo como parceiro veterano de um tipo a sua escolha por um dia."},
  {"id":"bucaneiro-aparar","nome":"Aparar","tipo":"Poder de bucaneiro","cat":"Bucaneiro","de":"Bucaneiro","fonteDe":"classe","desc":"Pré-requisito: Esgrimista. Uma vez por rodada, quando é atingido por um ataque, você pode gastar 1 PM para fazer um teste de ataque com bônus igual ao seu nível (além do normal). Se o resultado do seu teste for maior que o do oponente, você evita o ataque. Você só pode usar este poder se estiver usando uma arma corpo a corpo leve ou ágil."},
  {"id":"bucaneiro-bravata-audaz","nome":"Bravata Audaz","tipo":"Poder de bucaneiro","cat":"Bucaneiro","de":"Bucaneiro","fonteDe":"classe","desc":"Você jura fazer uma façanha específica, como roubar o tesouro de Sckhar ou ganhar um beijo do príncipe e da princesa até o fim do baile. Se cumprir a bravata, seus PM aumentam em +2 por nível de bucaneiro até o fim da aventura."},
  {"id":"bucaneiro-bravata-imprudente","nome":"Bravata Imprudente","tipo":"Poder de bucaneiro","cat":"Bucaneiro","de":"Bucaneiro","fonteDe":"classe","desc":"Na primeira rodada de um combate, você pode jurar derrotar seus inimigos com uma restrição a sua escolha, como lutar com uma mão nas costas, de guarda aberta (em termos de jogo, desprevenido), de olhos vendados (cego) etc. Uma restrição só é válida se prejudicá-lo (por exemplo, lutar com uma mão nas costas só vale como restrição se você luta com duas armas). O mestre tem a palavra final sobre a validade de uma restrição. Você sofre a penalidade durante todo o combate, mas, se vencer, recebe +2 nos testes de ataque e na margem de ameaça até o fim da aventura."},
  {"id":"bucaneiro-en-garde","nome":"En Garde","tipo":"Poder de bucaneiro","cat":"Bucaneiro","de":"Bucaneiro","fonteDe":"classe","desc":"Pré-requisito: Esgrimista. Você pode gastar uma ação de movimento e 1 PM para assumir postura de luta. Até o fim da cena, se estiver usando uma arma corpo a corpo leve ou ágil, você recebe +2 na margem de ameaça com essas armas e +2 na Defesa."},
  {"id":"bucaneiro-esgrimista","nome":"Esgrimista","tipo":"Poder de bucaneiro","cat":"Bucaneiro","de":"Bucaneiro","fonteDe":"classe","desc":"Pré-requisito: Int 13. Quando usa uma arma corpo a corpo leve ou ágil, você soma sua Inteligência nas rolagens de dano (limitado pelo seu nível)."},
  {"id":"bucaneiro-flagelo-mares","nome":"Flagelo dos Mares","tipo":"Poder de bucaneiro","cat":"Bucaneiro","de":"Bucaneiro","fonteDe":"classe","desc":"Pré-requisito: treinado em Intimidação. Você aprende e pode lançar Amedrontar (atributo-chave Carisma). Esta não é uma habilidade mágica e provém de sua capacidade de incutir medo em seus inimigos."},
  {"id":"bucaneiro-foliao","nome":"Folião","tipo":"Poder de bucaneiro","cat":"Bucaneiro","de":"Bucaneiro","fonteDe":"classe","desc":"Pré-requisito: Car 13. Você sabe fazer amizades durante festas, de noitadas em tavernas a bailes na corte. Nesses locais, você recebe +2 em testes de perícias de Carisma e a atitude de todas as pessoas em relação a você melhora em uma categoria."},
  {"id":"bucaneiro-grudar-cano","nome":"Grudar o Cano","tipo":"Poder de bucaneiro","cat":"Bucaneiro","de":"Bucaneiro","fonteDe":"classe","desc":"Pré-requisito: treinado em Luta, Pistoleiro. Quando faz um ataque à distância com uma arma de fogo contra um oponente adjacente, você não sofre a penalidade de –5 no teste de ataque e aumenta seu dano em um passo."},
  {"id":"bucaneiro-pernas-mar","nome":"Pernas do Mar","tipo":"Poder de bucaneiro","cat":"Bucaneiro","de":"Bucaneiro","fonteDe":"classe","desc":"Você recebe +2 em Acrobacia e Atletismo. Além disso, quando está se equilibrando ou escalando, você não fica desprevenido e seu deslocamento não é reduzido à metade."},
  {"id":"bucaneiro-pistoleiro","nome":"Pistoleiro","tipo":"Poder de bucaneiro","cat":"Bucaneiro","de":"Bucaneiro","fonteDe":"classe","desc":"Você recebe proficiência com armas de fogo e +2 nas rolagens de dano com essas armas."},
  {"id":"bucaneiro-presenca-paralisante","nome":"Presença Paralisante","tipo":"Poder de bucaneiro","cat":"Bucaneiro","de":"Bucaneiro","fonteDe":"classe","desc":"Pré-requisito: Car 13, 4º nível de bucaneiro. Você soma seu Carisma em Iniciativa e, se for o primeiro na iniciativa, ganha uma ação padrão extra na primeira rodada."},
  {"id":"bucaneiro-ripostar","nome":"Ripostar","tipo":"Poder de bucaneiro","cat":"Bucaneiro","de":"Bucaneiro","fonteDe":"classe","desc":"Pré-requisito: Aparar, 12º nível de bucaneiro. Quando usa a habilidade aparar e evita o ataque, você pode gastar 1 PM. Se fizer isso, pode fazer um ataque corpo a corpo imediato contra o inimigo que o atacou (se ele estiver em alcance)."},
  {"id":"bucaneiro-touche","nome":"Touché","tipo":"Poder de bucaneiro","cat":"Bucaneiro","de":"Bucaneiro","fonteDe":"classe","desc":"Pré-requisito: Esgrimista, 10º nível de bucaneiro. Quando se aproxima de um inimigo e o ataca com uma arma corpo a corpo leve ou ágil no mesmo turno, você pode gastar 2 PM para aumentar seu dano em um passo e receber +5 na margem de ameaça neste ataque."},
  {"id":"cacador-ambidestria","nome":"Ambidestria","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Pré-requisito: Des 15. Se estiver empunhando duas armas (e pelo menos uma delas for leve) e fizer a ação agredir, você pode fazer dois ataques, um com cada arma. Se fizer isso, sofre –2 em todos os testes de ataque até o seu próximo turno."},
  {"id":"cacador-armadilha-arataca","nome":"Armadilha: Arataca","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"A vítima sofre 2d6 pontos de dano de perfuração e fica agarrada. Uma criatura agarrada pode escapar com uma ação padrão e um teste de Força ou Acrobacia (CD Sab)."},
  {"id":"cacador-armadilha-espinhos","nome":"Armadilha: Espinhos","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"A vítima sofre 6d6 pontos de dano de perfuração. Um teste de Reflexos (CD Sab) reduz o dano à metade."},
  {"id":"cacador-armadilha-laco","nome":"Armadilha: Laço","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"A vítima deve fazer um teste de Reflexos (CD Sab). Se passar, fica caída. Se falhar, fica agarrada. Uma criatura agarrada pode se soltar com uma ação padrão e um teste de Força ou Acrobacia (CD Sab)."},
  {"id":"cacador-armadilha-rede","nome":"Armadilha: Rede","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Todas as criaturas na área ficam enredadas e não podem sair da área. Uma vítima pode se libertar com uma ação padrão e um teste de Força ou Acrobacia (CD 25). Além disso, a área ocupada pela rede é considerada terreno difícil. Nesta armadilha você escolhe quantas criaturas precisam estar na área para ativá-la."},
  {"id":"cacador-armadilheiro","nome":"Armadilheiro","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Pré-requisito: um poder de armadilha, 5º nível de caçador. Você soma sua Sabedoria no dano e na CD de suas armadilhas (cumulativo)."},
  {"id":"cacador-arqueiro","nome":"Arqueiro","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Pré-requisito: Sab 13. Se estiver usando uma arma de ataque à distância, você soma sua Sabedoria nas rolagens de dano (limitado pelo seu nível)."},
  {"id":"cacador-aumento-atributo","nome":"Aumento de Atributo","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo."},
  {"id":"cacador-bote","nome":"Bote","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Pré-requisito: Ambidestria, 6º nível de caçador. Se estiver empunhando duas armas e fizer uma investida, você pode pagar 1 PM para fazer um ataque adicional com sua arma secundária."},
  {"id":"cacador-camuflagem","nome":"Camuflagem","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Pré-requisito: 6º nível de caçador. Você pode gastar 2 PM para se esconder mesmo sem camuflagem ou cobertura disponível."},
  {"id":"cacador-chuva-laminas","nome":"Chuva de Lâminas","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Pré-requisito: Des 19, Ambidestria, 12º nível de caçador. Uma vez por rodada, quando usa Ambidestria, você pode pagar 2 PM para fazer um ataque adicional com sua arma primária."},
  {"id":"cacador-companheiro-animal","nome":"Companheiro Animal","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Pré-requisito: Car 13, treinado em Adestramento. Você recebe um companheiro animal. Veja o quadro na página 62."},
  {"id":"cacador-elo-natureza","nome":"Elo com a Natureza","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Pré-requisito: Sab 13, 3º nível de caçador. Você soma sua Sabedoria em seu total de pontos de mana e aprende e pode lançar Caminhos da Natureza (atributo-chave Sabedoria)."},
  {"id":"cacador-emboscar","nome":"Emboscar","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Pré-requisito: treinado em Furtividade. Você pode gastar 2 PM para realizar uma ação padrão adicional em seu turno. Você só pode usar este poder na primeira rodada de um combate."},
  {"id":"cacador-empatia-selvagem","nome":"Empatia Selvagem","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Você pode se comunicar com animais por meio de linguagem corporal e vocalizações. Você pode usar Adestramento com animais para mudar atitude e persuasão (veja Diplomacia, na página 118)."},
  {"id":"cacador-ervas-curativas","nome":"Ervas Curativas","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Você pode gastar uma ação completa e uma quantidade de PM a sua escolha (limitado por sua Sabedoria) para aplicar ervas que curam ou desintoxicam em você ou num aliado adjacente. Para cada PM que gastar, cura 2d6 PV ou remove uma condição envenenado afetando o alvo."},
  {"id":"cacador-escaramuca","nome":"Escaramuça","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Pré-requisito: Des 15, 6º nível de caçador. Quando se move 6m ou mais, você recebe +2 na Defesa e Reflexos e +1d8 nas rolagens de dano de ataques corpo a corpo e à distância em alcance curto até o início de seu próximo turno. Você não pode usar esta habilidade se estiver vestindo armadura pesada."},
  {"id":"cacador-escaramuca-superior","nome":"Escaramuça Superior","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Pré-requisito: Escaramuça, 12º nível de caçador. Quando usa Escaramuça, seus bônus aumentam para +5 na Defesa e Reflexos e +1d12 em rolagens de dano."},
  {"id":"cacador-espreitar","nome":"Espreitar","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Quando usa a habilidade Marca da Presa, você recebe um bônus de +1 em testes de perícia contra a criatura marcada. Esse bônus aumenta em +1 para cada PM adicional gasto na habilidade e também dobra com a habilidade Inimigo."},
  {"id":"cacador-explorador","nome":"Explorador","tipo":"Habilidade de classe","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"No 3º nível, escolha um tipo de terreno entre aquático, ártico, colina, deserto, floresta, montanha, pântano, planície, subterrâneo ou urbano. A partir do 11º nível, você também pode escolher área de Tormenta. Quando estiver no tipo de terreno escolhido, você soma sua Sabedoria (mínimo +1) na Defesa e nos testes de Acrobacia, Atletismo, Furtividade, Percepção e Sobrevivência. A cada quatro níveis, escolha outro tipo de terreno para receber o bônus ou aumente o bônus em um tipo de terreno já escolhido em +2.","nivel":3},
  {"id":"cacador-impeto","nome":"Ímpeto","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Você pode gastar 1 PM para aumentar seu deslocamento em +6m por uma rodada."},
  {"id":"cacador-inimigo-criatura","nome":"Inimigo de (Criatura)","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Escolha um tipo de criatura entre animal, construto, espírito, monstro ou morto-vivo, ou duas raças humanoides (por exemplo, orcs e gnolls, ou elfos e qareen). Quando você usa a habilidade Marca da Presa contra uma criatura do tipo ou da raça escolhida, dobra os dados de bônus no dano. O nome desta habilidade varia de acordo com o tipo de criatura escolhida (Inimigo de Monstros, Inimigo de Mortos-Vivos etc.). Você pode escolher este poder outras vezes para inimigos diferentes."},
  {"id":"cacador-olho-falcao","nome":"Olho do Falcão","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Você pode usar a habilidade Marca da Presa em criaturas em alcance longo."},
  {"id":"cacador-ponto-fraco","nome":"Ponto Fraco","tipo":"Poder de caçador","cat":"Caçador","de":"Caçador","fonteDe":"classe","desc":"Quando usa a habilidade Marca da Presa, seus ataques contra a criatura marcada recebem +2 na margem de ameaça. Esse bônus dobra com a habilidade Inimigo."},
  {"id":"cavaleiro-armadura-honra","nome":"Armadura da Honra","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"No início de cada cena, você recebe uma quantidade de pontos de vida temporários igual a seu nível + seu Carisma. Os PV temporários duram até o final da cena."},
  {"id":"cavaleiro-aumento-atributo","nome":"Aumento de Atributo","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo."},
  {"id":"cavaleiro-autoridade-feudal","nome":"Autoridade Feudal","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Pré-requisito: 6º nível de cavaleiro. Você pode gastar uma hora e 2 PM para conclamar o povo a ajudá-lo (qualquer pessoa sem um título de nobreza ou uma posição numa igreja reconhecida pelo seu reino). Em termos de jogo, essas pessoas contam como um parceiro iniciante de um tipo a sua escolha (aprovado pelo mestre) que lhe acompanha até o fim da aventura. Esta habilidade só pode ser usada em locais onde sua posição carregue alguma influência (a critério do mestre)."},
  {"id":"cavaleiro-caminho-cavaleiro","nome":"Caminho do Cavaleiro","tipo":"Habilidade de classe","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"No 5º nível, escolha entre Bastião ou Montaria (cada uma está listada como uma habilidade própria).","nivel":5},
  {"id":"cavaleiro-caminho-cavaleiro-bastiao","nome":"Caminho do Cavaleiro: Bastião","tipo":"Habilidade de classe","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Se estiver usando armadura pesada, você recebe redução de dano 5 (cumulativa com a RD fornecida por Especialização em Armadura)."},
  {"id":"cavaleiro-caminho-cavaleiro-montaria","nome":"Caminho do Cavaleiro: Montaria","tipo":"Habilidade de classe","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Você recebe um cavalo de guerra com o qual possui +5 em testes de Adestramento e Cavalgar. Ele fornece os benefícios de um parceiro veterano de seu tipo. No 11º nível, passa a fornecer os benefícios de um parceiro mestre. De acordo com o mestre, você pode receber outro tipo de montaria. Veja a lista de montarias na página 261. Caso a montaria morra, você pode comprar outra pelo preço normal e treiná-la para receber os benefícios desta habilidade com uma semana de trabalho."},
  {"id":"cavaleiro-desprezar-covardes","nome":"Desprezar os Covardes","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Você recebe redução de dano 5 se estiver caído, desprevenido ou flanqueado."},
  {"id":"cavaleiro-escudeiro","nome":"Escudeiro","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Você recebe os serviços de um escudeiro, um parceiro especial que cuida de seu equipamento. Suas armas fornecem +1 em rolagens de dano e sua armadura concede +1 na Defesa. Além disso, você pode pagar 1 PM para receber ajuda do escudeiro em combate. Você recebe uma ação de movimento que pode usar para se levantar, sacar um item ou trazer sua montaria. O escudeiro não conta em seu limite de parceiros. Caso ele morra, você pode treinar outro com um mês de trabalho."},
  {"id":"cavaleiro-especializacao-armadura","nome":"Especialização em Armadura","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Pré-requisito: 12º nível de cavaleiro. Se estiver usando armadura pesada, você recebe redução de dano 5 (cumulativa com a RD fornecida por Bastião)."},
  {"id":"cavaleiro-estandarte","nome":"Estandarte","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Pré-requisito: Título, 14º nível de cavaleiro. Sua flâmula torna-se um símbolo de inspiração. No início de cada cena, você e todos os aliados que possam ver seu estandarte recebem um número de PM temporários igual ao seu Carisma (mínimo 1). Esses pontos temporários desaparecem no final da cena."},
  {"id":"cavaleiro-etiqueta","nome":"Etiqueta","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Você recebe +2 em Diplomacia e Nobreza e quando faz um teste dessas perícias pode gastar 1 PM para rolá-lo novamente."},
  {"id":"cavaleiro-investida-destruidora","nome":"Investida Destruidora","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Quando faz a ação investida, você pode gastar 2 PM. Se fizer isso, causa +2d8 pontos de dano. Você deve usar esta habilidade antes de rolar o ataque."},
  {"id":"cavaleiro-montaria-corajosa","nome":"Montaria Corajosa","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Pré-requisito: Montaria. Sua montaria concede +1d6 em rolagens de dano corpo a corpo (cumulativo com qualquer bônus que ela já forneça como parceiro)."},
  {"id":"cavaleiro-pajem","nome":"Pajem","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Você recebe os serviços de um pajem, um parceiro que o auxilia em pequenos afazeres. Você recebe +2 em Diplomacia, por estar sempre aprumado, e sua condição de descanso é uma categoria acima do padrão pela situação (veja a página 106). O pajem pode executar pequenas tarefas, como entregar mensagens e comprar itens, e não conta em seu limite de parceiros. Caso ele morra, você pode treinar outro com uma semana de trabalho."},
  {"id":"cavaleiro-postura-combate-ariete-implacavel","nome":"Postura de Combate: Aríete Implacável","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Ao assumir esta postura, você aumenta o bônus de ataque em investidas em +2. Para cada 2 PM adicionais que gastar quando assumir a postura, aumenta o bônus de ataque em +1. Além disso, se fizer uma investida contra um construto ou objeto, causa +2d8 de dano. Você precisa se deslocar todos os turnos para manter esta postura ativa."},
  {"id":"cavaleiro-postura-combate-castigo-ferro","nome":"Postura de Combate: Castigo de Ferro","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Sempre que um aliado adjacente sofrer um ataque corpo a corpo, você pode gastar 1 PM para fazer um ataque na criatura que o atacou."},
  {"id":"cavaleiro-postura-combate-foco-batalha","nome":"Postura de Combate: Foco de Batalha","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Sempre que um inimigo atacá-lo, você recebe 1 PM temporário (cumulativos). Você pode ganhar um máximo de PM temporários por cena igual ao seu nível. Esses pontos temporários desaparecem no final da cena."},
  {"id":"cavaleiro-postura-combate-muralha-intransponivel","nome":"Postura de Combate: Muralha Intransponível","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Para assumir esta postura você precisa estar empunhando um escudo. Você recebe +1 na Defesa e em Reflexos. Além disso, quando sofre um efeito que permite um teste de Reflexos para reduzir o dano à metade, não sofre nenhum dano se passar. Para cada 2 PM adicionais que gastar quando assumir a postura, aumente esse bônus em +1. Por fim, enquanto mantiver esta postura, seu deslocamento é reduzido para 3m."},
  {"id":"cavaleiro-postura-combate-provocacao-petulante","nome":"Postura de Combate: Provocação Petulante","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Enquanto esta postura estiver ativa, todos os inimigos que iniciarem seus turnos em alcance curto devem fazer um teste de Vontade (CD Car). Se falharem, qualquer ação hostil que realizarem deve ter você como alvo (mas suas outras ações não têm esta restrição). Ações hostis incluem ataques e outras ações que causem dano e/ou condições negativas. Mental."},
  {"id":"cavaleiro-postura-combate-torre-inabalavel","nome":"Postura de Combate: Torre Inabalável","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Você assume uma postura defensiva que o torna imune a qualquer tentativa de tirá-lo do lugar, de forma mundana ou mágica. Enquanto mantiver a postura, você não pode se deslocar, mas soma sua Constituição na Defesa e pode substituir testes de Reflexos e Vontade por testes de Fortitude."},
  {"id":"cavaleiro-solidez","nome":"Solidez","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Se estiver usando um escudo, você soma o bônus na Defesa recebido pelo escudo em testes de resistência."},
  {"id":"cavaleiro-titulo","nome":"Título","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Pré-requisito: Autoridade Feudal, 10º nível de cavaleiro, ter conquistado terras ou realizado um serviço para um nobre que possa se tornar seu suserano. Você adquire um título de nobreza. Converse com o mestre para definir os benefícios exatos de seu título. Como regra geral, no início de cada aventura você recebe 20 TO por nível de cavaleiro (rendimentos dos impostos) ou a ajuda de um parceiro veterano (um membro de sua corte)."},
  {"id":"cavaleiro-torre-armada","nome":"Torre Armada","tipo":"Poder de cavaleiro","cat":"Cavaleiro","de":"Cavaleiro","fonteDe":"classe","desc":"Quando um inimigo erra um ataque contra você, você pode gastar 1 PM. Se fizer isso, recebe +5 em rolagens de dano contra esse inimigo até o fim de seu próximo turno."},
  {"id":"clerigo-abencoar-arma","nome":"Abençoar Arma","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Você se torna proficiente na arma preferida de sua divindade. Se estiver empunhando essa arma, pode gastar uma ação de movimento e 3 PM para infundi-la com poder divino. Até o final da cena, a arma é considerada mágica e emite luz dourada ou púrpura (como uma tocha). Além disso, o dano da arma aumenta em um passo e você pode usar sua Sabedoria em testes de ataque e rolagens de dano com ela, em vez do atributo padrão (não cumulativo com efeitos que somam este atributo)."},
  {"id":"clerigo-aumento-atributo","nome":"Aumento de Atributo","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo."},
  {"id":"clerigo-autoridade-eclesiastica","nome":"Autoridade Eclesiástica","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Você possui uma posição formal em uma igreja reconhecida pelos outros membros de sua fé. Os efeitos deste poder variam de acordo com a igreja e o deus — clérigos de Khalmyr, por exemplo, possuem autoridade como juízes no Reinado — e ficam a cargo do mestre. Como regra geral, você recebe +5 em testes de Diplomacia ou Intimidação ao lidar com devotos de sua divindade e paga metade do preço de itens alquímicos, poções e serviços em templos de sua divindade."},
  {"id":"clerigo-canalizar-amplo","nome":"Canalizar Amplo","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Pré-requisito: Canalizar Energia Positiva ou Negativa. Quando você usa a habilidade Canalizar Energia, pode gastar +2 PM para aumentar o alcance dela para médio."},
  {"id":"clerigo-canalizar-energia-positiva-negativa","nome":"Canalizar Energia Positiva/Negativa","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Você pode gastar uma ação padrão e PM para liberar uma onda de luz (se sua divindade canaliza energia positiva) ou trevas (se canaliza energia negativa) que afeta criaturas a sua escolha em alcance curto. Para cada PM que gastar, luz cura 1d6 PV em criaturas vivas e causa 1d6 pontos de dano de luz em mortos-vivos (Vontade CD Sab reduz o dano à metade). Trevas tem o efeito inverso — causa dano de trevas a criaturas vivas e cura mortos-vivos."},
  {"id":"clerigo-comunhao-vital","nome":"Comunhão Vital","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Quando lança uma magia que cure uma criatura, você pode pagar +2 PM para que outra criatura em alcance curto (incluindo você mesmo) recupere uma quantidade de pontos de vida igual à metade dos PV da cura original."},
  {"id":"clerigo-conhecimento-magico","nome":"Conhecimento Mágico","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Você aprende duas magias de qualquer círculo que possa lançar. Você pode escolher este poder quantas vezes quiser."},
  {"id":"clerigo-devoto-fiel","nome":"Devoto Fiel","tipo":"Habilidade de classe","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Você se torna devoto de um deus maior. Veja as regras de devotos na página 96. Ao contrário de devotos normais, você recebe dois poderes concedidos por se tornar devoto, em vez de apenas um. Como alternativa, você pode cultuar o Panteão como um todo. Não recebe nenhum Poder Concedido, mas sua única obrigação e restrição é não usar armas cortantes ou perfurantes (porque derramam sangue, algo que clérigos do Panteão consideram proibido). Sua arma preferida é a maça e você pode canalizar energia positiva ou negativa a sua escolha (uma vez feita, essa escolha não pode ser mudada). Cultuar o Panteão conta como sua devoção."},
  {"id":"clerigo-expulsar-comandar-mortos-vivos","nome":"Expulsar/Comandar Mortos-Vivos","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Pré-requisito: Canalizar Energia Positiva ou Negativa. Você pode gastar uma ação padrão e 3 PM para expulsar (se sua divindade canaliza energia positiva) ou comandar (se canaliza energia negativa) todos os mortos-vivos em alcance curto. Mortos-vivos expulsos ficam apavorados por 1d6 rodadas. Mortos-vivos comandados não inteligentes (Int –4 ou menor) ficam sob suas ordens por um dia (até um limite de ND somados igual a seu nível +3; dar uma ordem a todos eles é uma ação de movimento) e mortos-vivos comandados inteligentes ficam fascinados por uma rodada. Mortos-vivos têm direito a um teste de Vontade (CD Sab) para evitar qualquer destes efeitos."},
  {"id":"clerigo-liturgia-magica","nome":"Liturgia Mágica","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Você pode gastar uma ação de movimento para executar uma breve liturgia de sua fé. Se fizer isso, a CD para resistir à sua próxima habilidade de clérigo (desde que usada até o final de seu próximo turno) aumenta em +2."},
  {"id":"clerigo-magia-sagrada-profana","nome":"Magia Sagrada/Profana","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Quando lança uma magia divina que causa dano, você pode gastar +1 PM. Se fizer isso, muda o tipo de dano da magia para luz (se sua divindade canaliza energia positiva) ou trevas (se canaliza energia negativa)."},
  {"id":"clerigo-mestre-celebrante","nome":"Mestre Celebrante","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Pré-requisito: qualquer poder de Missa, 12º nível de clérigo. O número de pessoas que você afeta com uma missa aumenta em dez vezes e os benefícios que elas recebem dobram."},
  {"id":"clerigo-missa-bencao-vida","nome":"Missa: Bênção da Vida","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Os participantes recebem pontos de vida temporários em um valor igual ao seu nível + sua Sabedoria."},
  {"id":"clerigo-missa-chamado-armas","nome":"Missa: Chamado às Armas","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Os participantes recebem +1 em testes de ataque e rolagens de dano."},
  {"id":"clerigo-missa-elevacao-espirito","nome":"Missa: Elevação do Espírito","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Os participantes recebem pontos de mana temporários em um valor igual a sua Sabedoria."},
  {"id":"clerigo-missa-escudo-divino","nome":"Missa: Escudo Divino","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Os participantes recebem +1 na Defesa e testes de resistência."},
  {"id":"clerigo-missa-superar-limitacoes","nome":"Missa: Superar as Limitações","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Cada participante recebe +1d6 num único teste a sua escolha e pode usá-lo mesmo após rolar o dado."},
  {"id":"clerigo-prece-combate","nome":"Prece de Combate","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Quando lança uma magia divina com tempo de conjuração de uma ação padrão em si mesmo, você pode gastar +2 PM para lançá-la como uma ação de movimento."},
  {"id":"clerigo-simbolo-sagrado-energizado","nome":"Símbolo Sagrado Energizado","tipo":"Poder de clérigo","cat":"Clérigo","de":"Clérigo","fonteDe":"classe","desc":"Você pode gastar uma ação de movimento e 1 PM para fazer uma prece e energizar seu símbolo sagrado até o fim da cena. Um símbolo sagrado energizado emite uma luz dourada ou prateada (se sua divindade canaliza energia positiva) ou púrpura ou avermelhada (se canaliza energia negativa) que ilumina como uma tocha. Enquanto você estiver empunhando um símbolo sagrado energizado, o custo em PM para lançar suas magias divinas diminui em 1."},
  {"id":"druida-aspecto-primavera","nome":"Aspecto da Primavera","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Você aprende e pode lançar uma magia de encantamento ou ilusão, arcana ou divina, de qualquer círculo que possa lançar. Além disso, escolha uma quantidade de magias igual ao seu Carisma (mínimo 1). O custo dessas magias é reduzido em −1 PM."},
  {"id":"druida-aspecto-inverno","nome":"Aspecto do Inverno","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Você aprende e pode lançar uma magia de convocação ou evocação, arcana ou divina, de qualquer círculo que possa lançar. Além disso, recebe redução de frio 5 e suas magias que causam dano de frio causam +1 ponto de dano por dado."},
  {"id":"druida-aspecto-outono","nome":"Aspecto do Outono","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Você aprende e pode lançar uma magia de necromancia, arcana ou divina, de qualquer círculo que possa lançar. Além disso, pode gastar 1 PM para impor uma penalidade de –2 nos testes de resistência de todos os inimigos em alcance curto até o início do seu próximo turno."},
  {"id":"druida-aspecto-verao","nome":"Aspecto do Verão","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Você aprende e pode lançar uma magia de transmutação, arcana ou divina, de qualquer círculo que possa lançar. Além disso, pode gastar 1 PM para cobrir uma de suas armas com chamas até o fim da cena. A arma causa +1d6 pontos de dano de fogo. Sempre que você acertar um ataque com ela em combate, recebe 1 PM temporário. Você pode ganhar um máximo de PM temporários por cena igual ao seu nível e eles desaparecem no fim da cena."},
  {"id":"druida-aumento-atributo","nome":"Aumento de Atributo","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo."},
  {"id":"druida-companheiro-animal","nome":"Companheiro Animal","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Pré-requisito: Car 13, treinado em Adestramento. Você recebe um companheiro animal. Veja o quadro para detalhes. Você pode escolher este poder quantas vezes quiser, mas deve escolher companheiros diferentes e ainda está sujeito ao limite de parceiros que pode ter (veja a página 260). Companheiro Animal Um companheiro animal é um amigo valoroso e fiel. Você decide de qual espécie é seu companheiro. Vocês têm um vínculo mental, sendo capazes de entender um ao outro. Seu companheiro animal obedece a você, mesmo que isso arrisque a vida dele. Em termos de jogo, seu companheiro animal é um parceiro ajudante, assassino, atirador, combatente, fortão, guardião, perseguidor, ou uma montaria, do nível iniciante. No 7º nível ele muda para veterano e, no 15º nível, para mestre (se tiver mais de um tipo, todos mudam de nível). Se o companheiro animal morrer, você fica atordoado por uma rodada. Você pode invocar um novo companheiro após um dia inteiro de prece e meditação. A seguir, alguns exemplos de animais (mas você é livre para escolher outros). Veja a página 260 para as regras de parceiros. Ajudante. Corvo, macaco, raposa, serpente ou outro animal ágil ou esperto. Assassino. Lince, onça ou outro animal treinado para abater presas. Atirador. Águia, falcão ou outro animal capaz de mergulhar rapidamente nos alvos de seus ataques à distância. Fortão. Crocodilo, javali, leão, lobo ou outro animal capaz de lutar ao seu lado. Guardião. Alce, cão, coruja, tartaruga, urso ou outro animal pesado ou atento. Perseguidor. Gambá, sabujo ou outro animal farejador."},
  {"id":"druida-companheiro-animal-aprimorado","nome":"Companheiro Animal Aprimorado","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Pré-requisito: Companheiro Animal, 6º nível de druida. Escolha um de seus companheiros animais. Ele recebe um segundo tipo, ganhando os bônus de seu nível. Por exemplo, se você tiver um companheiro guardião veterano, pode adicionar o tipo fortão a ele, tornando-o um guardião fortão veterano que concede +3 na Defesa e +1d12 em uma rolagem de dano corpo a corpo."},
  {"id":"druida-companheiro-animal-lendario","nome":"Companheiro Animal Lendário","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Pré-requisito: Companheiro Animal, 18º nível de druida. Escolha um de seus companheiros animais. Esse animal passa a dobrar os bônus concedidos de seu tipo original."},
  {"id":"druida-companheiro-animal-magico","nome":"Companheiro Animal Mágico","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Pré-requisito: Companheiro Animal, 8º nível de druida. Escolha um de seus companheiros animais. Ele recebe um segundo tipo diferente, entre adepto, destruidor, magivocador ou médico, ganhando os bônus de seu nível."},
  {"id":"druida-coracao-selva","nome":"Coração da Selva","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"A CD para resistir a seus efeitos de veneno aumenta em +2 e estes efeitos causam +1 de perda de vida por dado."},
  {"id":"druida-devoto-fiel","nome":"Devoto Fiel","tipo":"Habilidade de classe","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Você se torna devoto de um deus disponível para druidas (Allihanna, Megalokk ou Oceano). Veja as regras de devotos na página 96. Ao contrário de devotos normais, você recebe dois poderes concedidos por se tornar devoto, em vez de apenas um."},
  {"id":"druida-espirito-equinocios","nome":"Espírito dos Equinócios","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Pré-requisito: Aspecto da Primavera, Aspecto do Outono, 10º nível de druida. Você pode gastar 4 PM para ficar em equilíbrio com o mundo. Até o final da cena, quando rola um dado, pode rolar novamente qualquer resultado 1."},
  {"id":"druida-espirito-solsticios","nome":"Espírito dos Solstícios","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Pré-requisito: Aspecto do Inverno, Aspecto do Verão, 10º nível de druida. Você transita entre os extremos do mundo natural. Quando lança uma magia, pode gastar +4 PM para maximizar os efeitos numéricos variáveis dela. Por exemplo, uma magia Curar Ferimentos aprimorada para curar 5d8+5 PV irá curar automaticamente 45 PV, sem a necessidade de rolar dados. Uma magia sem efeitos variáveis não pode ser afetada por este poder."},
  {"id":"druida-forca-penhascos","nome":"Força dos Penhascos","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Você recebe +2 em Fortitude. Quando sofre dano enquanto em contato com o solo ou uma superfície de pedra, pode gastar uma quantidade de PM limitada por sua Sabedoria. Para cada PM gasto, reduz esse dano em 10."},
  {"id":"druida-forma-primal","nome":"Forma Primal","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Pré-requisito: 18º nível de druida. Quando usa Forma Selvagem, você pode se transformar em uma fera primal. Você recebe os benefícios de dois tipos de animais (bônus iguais não se acumulam; use o que você quiser de cada tipo)."},
  {"id":"druida-forma-selvagem","nome":"Forma Selvagem","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Você pode se transformar em animais (veja a seguir)."},
  {"id":"druida-forma-selvagem-aprimorada","nome":"Forma Selvagem Aprimorada","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Pré-requisito: Forma Selvagem, 6º nível de druida. Quando usa Forma Selvagem, você pode gastar 6 PM ao todo para assumir uma forma aprimorada."},
  {"id":"druida-forma-selvagem-superior","nome":"Forma Selvagem Superior","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Pré-requisito: Forma Selvagem Aprimorada, 12º nível de druida. Quando usa Forma Selvagem, você pode gastar 10 PM ao todo para assumir uma forma superior."},
  {"id":"druida-liberdade-pradaria","nome":"Liberdade da Pradaria","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Você recebe +2 em Reflexos. Se estiver ao ar livre, sempre que lança uma magia, pode gastar 1 PM para aumentar o alcance dela em um passo (de toque para curto, de curto para médio ou de médio para longo)."},
  {"id":"druida-magia-natural","nome":"Magia Natural","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Pré-requisito: Forma Selvagem. Em forma selvagem, você pode lançar magias e empunhar catalisadores e esotéricos."},
  {"id":"druida-presas-afiadas","nome":"Presas Afiadas","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"A margem de ameaça de suas armas naturais aumenta em +2."},
  {"id":"druida-segredos-natureza","nome":"Segredos da Natureza","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Você aprende duas magias de qualquer círculo que possa lançar. Elas devem pertencer às escolas que você sabe usar, mas podem ser arcanas ou divinas. Você pode escolher este poder quantas vezes quiser."},
  {"id":"druida-tranquilidade-lagos","nome":"Tranquilidade dos Lagos","tipo":"Poder de druida","cat":"Druida","de":"Druida","fonteDe":"classe","desc":"Você recebe +2 em Vontade. Se estiver portando um recipiente com água (não precisa estar empunhando), uma vez por rodada, quando faz um teste de resistência, pode pagar 1 PM para refazer a rolagem."},
  {"id":"guerreiro-ambidestria","nome":"Ambidestria","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Pré-requisito: Des 15. Se estiver empunhando duas armas (e pelo menos uma delas for leve) e fizer a ação agredir, você pode fazer dois ataques, um com cada arma. Se fizer isso, sofre –2 em todos os testes de ataque até o seu próximo turno."},
  {"id":"guerreiro-arqueiro","nome":"Arqueiro","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Pré-requisito: Sab 13. Se estiver usando uma arma de ataque à distância, você soma sua Sabedoria em rolagens de dano (limitado pelo seu nível)."},
  {"id":"guerreiro-ataque-reflexo","nome":"Ataque Reflexo","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Pré-requisito: Des 13. Se um alvo em alcance de seus ataques corpo a corpo ficar desprevenido ou se mover voluntariamente para fora do seu alcance, você pode gastar 1 PM para fazer um ataque corpo a corpo contra esse alvo (apenas uma vez por alvo a cada rodada)."},
  {"id":"guerreiro-aumento-atributo","nome":"Aumento de Atributo","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo."},
  {"id":"guerreiro-bater-correr","nome":"Bater e Correr","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Quando faz uma investida, você pode continuar se movendo após o ataque, até o limite de seu deslocamento. Se gastar 2 PM, pode fazer uma investida sobre terreno difícil e sem sofrer a penalidade de Defesa."},
  {"id":"guerreiro-destruidor","nome":"Destruidor","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Pré-requisito: For 13. Quando causa dano com uma arma corpo a corpo de duas mãos, você pode rolar novamente qualquer resultado 1 ou 2 da rolagem de dano da arma."},
  {"id":"guerreiro-esgrimista","nome":"Esgrimista","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Pré-requisito: Int 13. Quando usa uma arma corpo a corpo leve ou ágil, você soma sua Inteligência em rolagens de dano (limitado pelo seu nível)."},
  {"id":"guerreiro-especializacao-arma","nome":"Especialização em Arma","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Escolha uma arma. Você recebe +2 em rolagens de dano com essa arma. Você pode escolher este poder outras vezes para armas diferentes."},
  {"id":"guerreiro-especializacao-armadura","nome":"Especialização em Armadura","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Pré-requisito: 12º nível de guerreiro. Você recebe redução de dano 5 se estiver usando uma armadura pesada."},
  {"id":"guerreiro-golpe-raspao","nome":"Golpe de Raspão","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Uma vez por rodada, quando erra um ataque, você pode gastar 2 PM. Se fizer isso, causa metade do dano que causaria (ignorando efeitos que se aplicariam caso o ataque acertasse)."},
  {"id":"guerreiro-golpe-demolidor","nome":"Golpe Demolidor","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Quando usa a manobra quebrar ou ataca um objeto, você pode gastar 2 PM para ignorar a redução de dano dele."},
  {"id":"guerreiro-golpe-pessoal","nome":"Golpe Pessoal","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Pré-requisito: 5º nível de guerreiro. Quando faz um ataque, você pode desferir seu Golpe Pessoal, uma técnica única, com efeitos determinados por você. Você constrói seu Golpe Pessoal escolhendo efeitos da lista a seguir. Cada efeito possui um custo; a soma deles será o custo do Golpe Pessoal (mínimo 1 PM). O Golpe Pessoal só pode ser usado com uma arma específica (por exemplo, apenas espadas longas). Quando sobe de nível, você pode reconstruir seu Golpe Pessoal e alterar a arma que ele usa. Você pode escolher este poder outras vezes para golpes diferentes e não pode gastar mais PM em golpes pessoais em uma mesma rodada do que seu limite de PM."},
  {"id":"guerreiro-impeto","nome":"Ímpeto","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Você pode gastar 1 PM para aumentar seu deslocamento em +6m por uma rodada."},
  {"id":"guerreiro-mestre-arma","nome":"Mestre em Arma","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Pré-requisito: Especialização em Arma com a arma escolhida, 12º nível de guerreiro. Escolha uma arma. Com esta arma, seu dano aumenta em um passo e quando faz um teste de ataque você pode gastar 2 PM para rolá-lo novamente."},
  {"id":"guerreiro-planejamento-marcial","nome":"Planejamento Marcial","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Pré-requisito: treinado em Guerra, 10º nível de guerreiro. Uma vez por dia, você pode gastar uma hora e 3 PM para escolher um poder de guerreiro ou de combate cujos pré-requisitos cumpra. Você recebe os benefícios desse poder até o próximo dia."},
  {"id":"guerreiro-romper-resistencias","nome":"Romper Resistências","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Quando faz um Ataque Especial, você pode gastar 1 PM adicional para ignorar 10 pontos de redução de dano."},
  {"id":"guerreiro-solidez","nome":"Solidez","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Se estiver usando um escudo, você aplica o bônus na Defesa recebido pelo escudo em testes de resistência."},
  {"id":"guerreiro-tornado-dor","nome":"Tornado de Dor","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Pré-requisito: 6º nível de guerreiro. Você pode gastar uma ação padrão e 2 PM para desferir uma série de golpes giratórios. Faça um ataque corpo a corpo e compare-o com a Defesa de cada inimigo em seu alcance natural. Então faça uma rolagem de dano com um bônus cumulativo de +2 para cada acerto e aplique-a em cada inimigo atingido."},
  {"id":"guerreiro-valentao","nome":"Valentão","tipo":"Poder de guerreiro","cat":"Guerreiro","de":"Guerreiro","fonteDe":"classe","desc":"Você recebe +2 em testes de ataque e rolagens de dano contra oponentes caídos, desprevenidos, flanqueados ou indefesos."},
  {"id":"inventor-agite-antes-usar","nome":"Agite Antes de Usar","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: treinado em Ofício (alquimista). Quando usa um preparado alquímico que cause dano, você pode gastar uma quantidade de PM a sua escolha (limitado por sua Inteligência). Para cada PM que gastar, o item causa um dado extra de dano do mesmo tipo."},
  {"id":"inventor-ajuste-mira","nome":"Ajuste de Mira","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Balística. Você pode gastar uma ação padrão e uma quantidade de PM a sua escolha (limitado pela sua Inteligência) para aprimorar uma arma de ataque à distância. Para cada PM que gastar, você recebe +1 em rolagens de dano com a arma até o final da cena."},
  {"id":"inventor-alquimista-batalha","nome":"Alquimista de Batalha","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Alquimista Iniciado. Quando usa um preparado alquímico ou poção que cause dano, você soma sua Inteligência na rolagem de dano."},
  {"id":"inventor-alquimista-iniciado","nome":"Alquimista Iniciado","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Int 13, Sab 13, treinado em Ofício (alquimista). Você recebe um livro de fórmulas e pode fabricar poções com fórmulas que conheça de 1º e 2º círculos. Veja as páginas 333 e 341 para as regras de poções."},
  {"id":"inventor-armeiro","nome":"Armeiro","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: treinado em Luta e Ofício (armeiro). Você recebe proficiência com armas marciais corpo a corpo. Quando empunha uma arma corpo a corpo, pode usar sua Inteligência em vez de Força nos testes de ataque e rolagens de dano."},
  {"id":"inventor-ativacao-rapida","nome":"Ativação Rápida","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Engenhoqueiro, 7º nível de inventor. Ao ativar uma engenhoca com ação padrão, você pode pagar 2 PM para ativá-la com uma ação de movimento, em vez disto."},
  {"id":"inventor-aumento-atributo","nome":"Aumento de Atributo","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo."},
  {"id":"inventor-automato","nome":"Autômato","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Engenhoqueiro. Você fabrica um autômato, um construto que obedece a seus comandos. Ele é um parceiro iniciante de um tipo a sua escolha entre ajudante, assassino, atirador, combatente, guardião, montaria ou vigilante. No 7º nível, ele muda para veterano e, no você pode fabricar um novo com uma semana de trabalho e T$ 100."},
  {"id":"inventor-automato-prototipado","nome":"Autômato Prototipado","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Autômato. Você pode gastar uma ação padrão e 2 PM para ativar uma melhoria experimental em seu autômato. Role 1d6. Em um resultado 2 a 6, você aumenta o nível de parceiro do autômato em um passo (até mestre), ou concede a ele a habilidade iniciante de outro de seus tipos, até o fim da cena. Em um resultado 1, o autômato enguiça como uma engenhoca."},
  {"id":"inventor-balistica","nome":"Balística","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: treinado em Pontaria e Ofício (armeiro). Você recebe proficiência com armas marciais de ataque à distância ou com armas de fogo. Quando usa uma arma de ataque à distância, pode usar sua Inteligência em vez de Destreza nos testes de ataque (e, caso possua o poder Estilo de Disparo, nas rolagens de dano)."},
  {"id":"inventor-blindagem","nome":"Blindagem","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Couraceiro, 8º nível de inventor. Você pode usar sua Inteligência na Defesa quando usa armadura pesada. Se fizer isso, não pode somar sua Destreza, mesmo que outras habilidades ou efeitos permitam isso."},
  {"id":"inventor-cano-raiado","nome":"Cano Raiado","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Balística, 5º nível de inventor. Quando usa uma arma de disparo feita por você mesmo, ela recebe +1 na margem de ameaça."},
  {"id":"inventor-catalisador-instavel","nome":"Catalisador Instável","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Alquimista Iniciado. Você pode gastar uma ação completa e 3 PM para fabricar um preparado alquímico ou poção cuja fórmula conheça instantaneamente. O custo do item é reduzido à metade e você não precisa fazer o teste de Ofício (alquimista), mas ele só dura até o fim da cena."},
  {"id":"inventor-chutes-palavroes","nome":"Chutes e Palavrões","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Engenhoqueiro. Uma vez por rodada, quando faz um teste de Ofício (engenhoqueiro) para ativar uma engenhoca, você pode gastar 1 PM para rolá-lo novamente."},
  {"id":"inventor-conhecimento-formulas","nome":"Conhecimento de Fórmulas","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Alquimista Iniciado. Você aprende três fórmulas de quaisquer círculos que possa aprender. Você pode escolher este poder quantas vezes quiser."},
  {"id":"inventor-couraceiro","nome":"Couraceiro","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: treinado em Ofício (armeiro). Você recebe proficiência com armaduras pesadas e escudos. Quando usa armadura, pode usar sua Inteligência em vez de Destreza na Defesa (mas continua não podendo somar um atributo na Defesa quando usa armadura pesada)."},
  {"id":"inventor-engenhoqueiro","nome":"Engenhoqueiro","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Int 17, treinado em Ofício (engenhoqueiro). Você pode fabricar engenhocas. Veja as regras para isso na página 70."},
  {"id":"inventor-farmaceutico","nome":"Farmacêutico","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Sab 13, treinado em Ofício (alquimista). Quando usa um item alquímico que cure pontos de vida, você pode gastar uma quantidade de PM a sua escolha (limitado por sua Inteligência). Para cada PM que gastar, o item cura um dado extra do mesmo tipo."},
  {"id":"inventor-ferreiro","nome":"Ferreiro","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Armeiro, 5º nível de inventor. Quando usa uma arma corpo a corpo feita por você mesmo, o dano dela aumenta em um passo."},
  {"id":"inventor-granadeiro","nome":"Granadeiro","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Alquimista de Batalha. Você pode arremessar itens alquímicos e poções em alcance médio. Você pode usar sua Inteligência em vez de Destreza para calcular a CD do teste de resistência desses itens."},
  {"id":"inventor-homunculo","nome":"Homúnculo","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Alquimista Iniciado. Você possui um homúnculo, uma criatura Minúscula feita de alquimia. Vocês podem se comunicar telepaticamente em alcance longo e ele obedece a suas ordens, mas ainda está limitado ao que uma criatura de seu tamanho pode fazer. Um homúnculo é um parceiro ajudante iniciante. Você pode perder 1d6 pontos de vida para seu homúnculo assumir uma forma capaz de protegê-lo e se tornar também um parceiro guardião iniciante até o fim da cena."},
  {"id":"inventor-invencao-potente","nome":"Invenção Potente","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Quando usa um item ou engenhoca fabricado por você mesmo, você pode pagar 1 PM para aumentar em +2 a CD para resistir a ele."},
  {"id":"inventor-maestria-pericia","nome":"Maestria em Perícia","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Escolha um número de perícias treinadas igual a sua Inteligência, exceto bônus temporários. Quando faz um teste dessas perícias, você pode gastar 1 PM para escolher 10 em qualquer situação, exceto testes de ataque."},
  {"id":"inventor-manutencao-eficiente","nome":"Manutenção Eficiente","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Engenhoqueiro, 5º nível de inventor. A quantidade de engenhocas que você pode manter aumenta em +3. Além disso, cada engenhoca passa a ocupar meio espaço."},
  {"id":"inventor-mestre-alquimista","nome":"Mestre Alquimista","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Int 17, Sab 17, Alquimista Iniciado, 10º nível de inventor. Você pode fabricar poções com fórmulas que conheça de qualquer círculo."},
  {"id":"inventor-mestre-cuca","nome":"Mestre Cuca","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: treinado em Ofício (cozinheiro). Todas as comidas que você cozinha têm seu bônus numérico aumentado em +1."},
  {"id":"inventor-mistura-fervilhante","nome":"Mistura Fervilhante","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Alquimista Iniciado, 5º nível de inventor. Quando usa um item alquímico ou poção, você pode gastar 2 PM para dobrar a área de efeito dele."},
  {"id":"inventor-oficina-campo","nome":"Oficina de Campo","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: treinado em Ofício (armeiro). Você pode gastar uma hora e 2 PM para fazer a manutenção do equipamento de seu grupo. Cada membro do grupo escolhe uma arma, armadura ou escudo para manutenção. Armas recebem +1 em testes de ataque, armaduras e escudos aumentam seu bônus na Defesa em +1. Os benefícios duram um dia."},
  {"id":"inventor-pedra-amolar","nome":"Pedra de Amolar","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Armeiro. Você pode gastar uma ação de movimento e uma quantidade de PM a sua escolha (limitado por sua Inteligência) para aprimorar uma arma corpo a corpo que esteja empunhando. Para cada PM que gastar, você recebe +1 em rolagens de dano com a arma até o final da cena."},
  {"id":"inventor-prototipo","nome":"Protótipo","tipo":"Habilidade de classe","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Você começa o jogo com um item superior, ou com 10 itens alquímicos, com preço total de até T$ 500. Veja o Capítulo 3: Equipamento para a lista de itens."},
  {"id":"inventor-sintese-rapida","nome":"Síntese Rápida","tipo":"Poder de inventor","cat":"Inventor","de":"Inventor","fonteDe":"classe","desc":"Pré-requisito: Alquimista Iniciado. Quando fabrica um item alquímico ou poção, você pode fabricar o dobro de doses no mesmo tempo (pagando o custo de matéria-prima de cada uma)."},
  {"id":"ladino-assassinar","nome":"Assassinar","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Pré-requisito: 5º nível de ladino. Você pode gastar uma ação de movimento e 3 PM para analisar uma criatura em alcance curto. Até o fim de seu próximo turno, seu primeiro Ataque Furtivo que causar dano a ela tem seus dados de dano extras dessa habilidade dobrados."},
  {"id":"ladino-aumento-atributo","nome":"Aumento de Atributo","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo."},
  {"id":"ladino-contatos-submundo","nome":"Contatos no Submundo","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Quando chega em uma comunidade equivalente a uma vila ou maior, você pode gastar 2 PM para fazer um teste de Carisma (CD 10). Se passar, enquanto estiver nessa comunidade, recebe +5 em testes de Investigação para interrogar, pode comprar itens mundanos, poções e pergaminhos com 20% de desconto (não cumulativo com barganha e outros descontos) e, de acordo com o mestre, tem acesso a itens e serviços proibidos (como armas de pólvora e venenos)."},
  {"id":"ladino-emboscar","nome":"Emboscar","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Pré-requisito: treinado em Furtividade. Na primeira rodada de cada combate, você pode gastar 2 PM para executar uma ação padrão adicional em seu turno."},
  {"id":"ladino-escapista","nome":"Escapista","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Você recebe +5 em testes de Acrobacia para escapar, passar por espaço apertado e passar por inimigo e em testes para resistir a efeitos de movimento."},
  {"id":"ladino-especialista","nome":"Especialista","tipo":"Habilidade de classe","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Escolha um número de perícias treinadas igual a sua Inteligência, exceto bônus temporários (mínimo 1). Ao fazer um teste de uma dessas perícias, você pode gastar 1 PM para dobrar seu bônus de treinamento. Você não pode usar esta habilidade em testes de ataque."},
  {"id":"ladino-fuga-formidavel","nome":"Fuga Formidável","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Pré-requisito: Int 13. Você pode gastar uma ação completa e 1 PM para analisar o lugar no qual está (um castelo, um porto, a praça de uma cidade...). Até o fim da cena, recebe +3m em seu deslocamento, +5 em Acrobacia e Atletismo e ignora penalidades em movimento por terreno difícil. Você perde esses benefícios se fizer uma ação que não seja diretamente relacionada a fugir. Por exemplo, você só pode atacar um inimigo se ele estiver bloqueando seu caminho, agarrando-o etc. Você pode fazer ações para ajudar seus aliados, mas apenas se eles estiverem tentando escapar."},
  {"id":"ladino-gatuno","nome":"Gatuno","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Você recebe +2 em Atletismo. Quando escala, não fica desprevenido e avança seu deslocamento normal, em vez de metade dele."},
  {"id":"ladino-ladrao-arcano","nome":"Ladrão Arcano","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Pré-requisito: Roubo de Mana, 13º nível de ladino. Quando causa dano com um ataque furtivo em uma criatura capaz de lançar magias, você pode “roubar” uma magia que já a tenha visto lançar. Você precisa pagar 1 PM por círculo da magia e pode roubar magias de até 4º círculo. Até o fim da cena, você pode lançar a magia roubada (atributo-chave Inteligência)."},
  {"id":"ladino-mao-boca","nome":"Mão na Boca","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Pré-requisito: treinado em Luta. Você recebe +2 em testes de agarrar. Quando acerta um ataque furtivo contra uma criatura desprevenida, você pode fazer um teste de agarrar como uma ação livre. Se agarrar a criatura, ela não poderá falar enquanto estiver agarrada."},
  {"id":"ladino-maos-rapidas","nome":"Mãos Rápidas","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Pré-requisito: Des 15, treinado em Ladinagem. Uma vez por rodada, ao fazer um teste de Ladinagem para abrir fechaduras, ocultar item, punga ou sabotar, você pode pagar 1 PM para fazê-lo como uma ação livre."},
  {"id":"ladino-mente-criminosa","nome":"Mente Criminosa","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Pré-requisito: Int 13. Você soma sua Inteligência em Ladinagem e Furtividade."},
  {"id":"ladino-oportunismo","nome":"Oportunismo","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Pré-requisito: 6º nível de ladino. Uma vez por rodada, quando um inimigo adjacente sofre dano de um de seus aliados, você pode gastar 2 PM para fazer um ataque corpo a corpo contra este inimigo."},
  {"id":"ladino-rolamento-defensivo","nome":"Rolamento Defensivo","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Pré-requisito: treinado em Reflexos. Sempre que sofre dano, você pode gastar 2 PM para reduzir esse dano à metade. Após usar este poder, você fica caído."},
  {"id":"ladino-roubo-mana","nome":"Roubo de Mana","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Pré-requisito: Truque Mágico, 7º nível de ladino. Quando você causa dano com um ataque furtivo, para cada 1d6 de dano de seu ataque furtivo, você recebe 1 PM temporário e a criatura perde 1 ponto de mana (se tiver). Você só pode usar este poder uma vez por cena contra uma mesma criatura."},
  {"id":"ladino-saqueador-tumbas","nome":"Saqueador de Tumbas","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Você recebe +5 em testes de Investigação para encontrar armadilhas e em testes de resistência contra elas. Além disso, gasta uma ação padrão para desabilitar mecanismos, em vez de 1d4 rodadas (veja a perícia Ladinagem)."},
  {"id":"ladino-sombra","nome":"Sombra","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Pré-requisito: treinado em Furtividade. Você recebe +2 em Furtividade, não sofre penalidade em testes de Furtividade por se mover no seu deslocamento normal e reduz a penalidade por atacar e fazer outras ações chamativas para –10."},
  {"id":"ladino-truque-magico","nome":"Truque Mágico","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Pré-requisito: Int 13. Você aprende e pode lançar uma magia arcana de 1º círculo a sua escolha, pagando seu custo normal em PM. Seu atributo-chave para esta magia é Inteligência. Você pode escolher este poder quantas vezes quiser."},
  {"id":"ladino-velocidade-ladina","nome":"Velocidade Ladina","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Pré-requisito: Des 15, treinado em Iniciativa. Uma vez por rodada, você pode gastar 2 PM para realizar uma ação de movimento adicional em seu turno."},
  {"id":"ladino-veneno-persistente","nome":"Veneno Persistente","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Pré-requisito: Veneno Potente, 8º nível de ladino. Quando aplica uma dose de veneno a uma arma, este veneno dura por três ataques (em vez de apenas um)."},
  {"id":"ladino-veneno-potente","nome":"Veneno Potente","tipo":"Poder de ladino","cat":"Ladino","de":"Ladino","fonteDe":"classe","desc":"Pré-requisito: treinado em Ofício (alquimista). A CD para resistir aos venenos que você usa aumenta em +5."},
  {"id":"lutador-arma-improvisada","nome":"Arma Improvisada","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Para você, atacar com armas improvisadas conta como fazer um ataque desarmado, mas seu dano aumenta em um passo. Você pode gastar uma ação de movimento para procurar uma pedra, cadeira, garrafa ou qualquer coisa que possa usar como arma. Faça um teste de Percepção (CD 20). Se você passar, encontra uma arma improvisada. Armas improvisadas são frágeis; se você errar um ataque e o resultado do d20 for um número ímpar, a arma quebra."},
  {"id":"lutador-ate-acertar","nome":"Até Acertar","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Se você errar um ataque desarmado, recebe um bônus cumulativo de +2 em testes de ataque e rolagens de dano desarmado contra o mesmo oponente. Os bônus terminam quando você acertar um ataque ou no fim da cena, o que acontecer primeiro."},
  {"id":"lutador-aumento-atributo","nome":"Aumento de Atributo","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo."},
  {"id":"lutador-bracos-calejados","nome":"Braços Calejados","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Se você não estiver usando armadura, soma sua Força na Defesa, limitado pelo seu nível."},
  {"id":"lutador-cabecada","nome":"Cabeçada","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Quando faz um ataque desarmado, você pode gastar 2 PM. Se fizer isso, o oponente fica desprevenido contra este ataque. Você só pode usar este poder uma vez por cena contra um mesmo alvo."},
  {"id":"lutador-chave","nome":"Chave","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Pré-requisito: Int 13, Lutador de Chão, 4º nível de lutador. Se estiver agarrando uma criatura e fizer um teste de manobra contra ela para causar dano, o dano desarmado aumenta em um passo."},
  {"id":"lutador-confianca-ringues","nome":"Confiança dos Ringues","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Pré-requisito: 8º nível de lutador. Quando um inimigo erra um ataque corpo a corpo contra você, você recebe 2 PM temporários (cumulativos). Você pode ganhar um máximo de PM temporários por cena igual ao seu nível. Esses pontos temporários desaparecem no final da cena."},
  {"id":"lutador-convencido","nome":"Convencido","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Acostumado a contar apenas com seus músculos, você adquiriu certo desdém por artes mais sofisticadas. Você recebe resistência a medo e mental +5."},
  {"id":"lutador-golpe-baixo","nome":"Golpe Baixo","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Quando faz um ataque desarmado, você pode gastar 2 PM. Se fizer isso e acertar o ataque, o oponente deve fazer um teste de Fortitude (CD For). Se ele falhar, fica atordoado por uma rodada (apenas uma vez por cena)."},
  {"id":"lutador-golpe-imprudente","nome":"Golpe Imprudente","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Quando usa Golpe Relâmpago, você pode atacar de forma impulsiva. Se fizer isso, seus ataques desarmados recebem um dado de dano extra do mesmo tipo (por exemplo, se o seu dano é 2d6, você causa 3d6), mas você sofre –5 na Defesa até o início de seu próximo turno."},
  {"id":"lutador-imobilizacao","nome":"Imobilização","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Pré-requisito: Chave,. Se estiver agarrando uma criatura, você pode gastar uma ação completa para imobilizá-la. Faça um teste de manobra contra ela. Se você passar, imobiliza a criatura — ela fica indefesa e não pode realizar nenhuma ação, exceto tentar se soltar (o que exige um teste de manobra). Se a criatura se soltar da imobilização, ainda fica agarrada. Enquanto estiver imobilizando uma criatura, você sofre as penalidades de agarrar."},
  {"id":"lutador-lingua-becos","nome":"Língua dos Becos","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Pré-requisito: For 13, treinado em Intimidação. Quando faz um teste de perícia baseada em Carisma, você pode pagar 1 PM para usar sua Força no lugar deste atributo."},
  {"id":"lutador-lutador-chao","nome":"Lutador de Chão","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Você recebe +2 em testes de ataque para agarrar e derrubar. Quando agarra uma criatura, pode gastar 1 PM para fazer uma manobra derrubar contra ela como uma ação livre."},
  {"id":"lutador-nome-arena","nome":"Nome na Arena","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Pré-requisito: 11º nível de lutador. Você construiu uma reputação no circuito de lutas de Arton. Uma vez por cena, pode gastar uma ação completa para fazer um teste de Luta (CD 10) e impressionar os presentes. Se passar, você recebe +2 em todos os seus testes de perícias originalmente baseadas em Carisma até o fim da cena e a atitude de qualquer pessoa que seja fã de lutas aumenta em uma categoria em relação a você (veja a página 259). Esse bônus aumenta em +2 para cada 10 pontos pelos quais o resultado do teste exceder a CD (+4 para um resultado 20, +6 para 30 e assim por diante)."},
  {"id":"lutador-punhos-adamante","nome":"Punhos de Adamante","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Pré-requisito: 8º nível de lutador. Seus ataques desarmados ignoram 10 pontos de redução de dano do alvo, se houver."},
  {"id":"lutador-rasteira","nome":"Rasteira","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Quando faz um ataque desarmado contra uma criatura até uma categoria de tamanho maior que a sua, você pode gastar 2 PM. Se fizer isso e acertar o ataque, a criatura fica caída."},
  {"id":"lutador-sarado","nome":"Sarado","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Pré-requisito: For 17. Você soma sua Força no seu total de pontos de vida e em Fortitude. Você pode usar Força em vez de Carisma em testes de Diplomacia com pessoas que se atraiam por físicos bem definidos."},
  {"id":"lutador-sequencia-destruidora","nome":"Sequência Destruidora","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Pré-requisitos: Trocação, 12º nível de lutador. No início do seu turno, você pode gastar 2 PM para dizer um número (no mínimo 2). Se fizer e acertar uma quantidade de ataques igual ao número dito, o último recebe um bônus cumulativo de +4 na rolagem de dano por ataque feito. Por exemplo, se você falar “três” e fizer e acertar três ataques, o último ataque (o terceiro) receberá +12 na rolagem de dano."},
  {"id":"lutador-trincado","nome":"Trincado","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Pré-requisito: Con 17, Sarado, 10º nível de lutador. Esculpido à exaustão, seu corpo se tornou uma máquina. Você soma sua Constituição nas rolagens de dano desarmado."},
  {"id":"lutador-trocacao","nome":"Trocação","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Pré-requisito: 6º nível de lutador. Quando você começa a bater, não para mais. Ao acertar um ataque desarmado, pode fazer outro ataque desarmado contra o mesmo alvo, pagando uma quantidade de PM igual à quantidade de ataques já realizados por você na rodada. Ou seja, pode fazer o primeiro ataque extra gastando 1 PM, um segundo ataque extra gastando mais 2 PM e assim por diante, até errar um ataque ou não ter mais pontos de mana."},
  {"id":"lutador-trocacao-tumultuosa","nome":"Trocação Tumultuosa","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Pré-requisito: Trocação, 8º nível de lutador. Quando usa a ação agredir para fazer um ataque desarmado, você pode gastar 2 PM para atingir todas as criaturas adjacentes — incluindo aliados! Você deve usar este poder antes de rolar o ataque e compara o resultado de seu teste contra a Defesa de cada criatura."},
  {"id":"lutador-valentao","nome":"Valentão","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Você recebe +2 em testes de ataque e rolagens de dano contra oponentes caídos, desprevenidos, flanqueados ou indefesos."},
  {"id":"lutador-voadora","nome":"Voadora","tipo":"Poder de lutador","cat":"Lutador","de":"Lutador","fonteDe":"classe","desc":"Quando faz uma investida desarmada, você pode gastar 2 PM. Se fizer isso, recebe +1d6 no dano para cada 3m que se deslocar até chegar ao oponente, limitado pelo seu nível."},
  {"id":"nobre-armadura-brilhante","nome":"Armadura Brilhante","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Pré-requisito: 8º nível de nobre. Você pode usar seu Carisma na Defesa quando usa armadura pesada. Se fizer isso, não pode somar sua Destreza, mesmo que outras habilidades ou efeitos permitam isso."},
  {"id":"nobre-aumento-atributo","nome":"Aumento de Atributo","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo."},
  {"id":"nobre-autoridade-feudal","nome":"Autoridade Feudal","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Pré-requisito: 6º nível de nobre. Você pode gastar uma hora e 2 PM para conclamar o povo a ajudá-lo (qualquer pessoa sem um título de nobreza ou uma posição numa igreja reconhecida pelo seu reino). Em termos de jogo, essas pessoas contam como um parceiro iniciante de um tipo a sua escolha (aprovado pelo mestre) que lhe acompanha até o fim da aventura. Esta habilidade só pode ser usada em locais onde sua posição carregue alguma influência (a critério do mestre)."},
  {"id":"nobre-educacao-privilegiada","nome":"Educação Privilegiada","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Você se torna treinado em duas perícias de nobre a sua escolha."},
  {"id":"nobre-espolio","nome":"Espólio","tipo":"Habilidade de classe","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Você recebe um item a sua escolha com preço de até T$ 2.000."},
  {"id":"nobre-estrategista","nome":"Estrategista","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Pré-requisito: Int 13, treinado em Guerra, 6º nível de nobre. Você pode direcionar aliados em alcance curto. Gaste uma ação padrão e 1 PM por aliado que quiser direcionar (limitado pelo seu Carisma). No próximo turno do aliado, ele ganha uma ação de movimento."},
  {"id":"nobre-favor","nome":"Favor","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Você pode usar sua influência para pedir favores a pessoas poderosas. Isso gasta 5 PM e uma hora de conversa e bajulação, ou mais, de acordo com o mestre, e funciona como o uso persuasão de Diplomacia (veja a página 118). Porém, você pode pedir favores ainda mais caros, difíceis ou perigosos — um convite para uma festa particular, uma carona de barco até Galrasia ou mesmo acesso aos planos militares do reino. Se você falhar, não pode pedir o mesmo favor por pelo menos uma semana."},
  {"id":"nobre-general","nome":"General","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Pré-requisito: Estrategista, 12º nível de nobre. Quando você usa o poder Estrategista, aliados direcionados recebem 1d4 PM temporários. Esses PM duram até o fim do turno do aliado e não podem ser usados em efeitos que concedam PM."},
  {"id":"nobre-grito-tiranico","nome":"Grito Tirânico","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Pré-requisito: 8º nível de nobre. Você pode usar Palavras Afiadas como uma ação completa, em vez de padrão. Se fizer isso, seus dados de dano aumentam para d8 e você atinge todos os inimigos em alcance curto."},
  {"id":"nobre-inspirar-confianca","nome":"Inspirar Confiança","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Sua presença faz as pessoas darem o melhor de si. Quando um aliado em alcance curto faz um teste, você pode gastar 2 PM para fazer com que ele possa rolar esse teste novamente."},
  {"id":"nobre-inspirar-gloria","nome":"Inspirar Glória","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Pré-requisito: Inspirar Confiança, 8º nível de nobre. A presença de um nobre motiva as pessoas a realizarem grandes façanhas. Uma vez por rodada, você pode gastar 5 PM para fazer um aliado em alcance curto ganhar uma ação padrão adicional no próximo turno dele. Você só pode usar esta habilidade uma vez por cena em cada aliado."},
  {"id":"nobre-jogo-corte","nome":"Jogo da Corte","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Quando faz um teste de Diplomacia, Intuição ou Nobreza, você pode gastar 1 PM para rolá-lo novamente."},
  {"id":"nobre-liderar-exemplo","nome":"Liderar pelo Exemplo","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Pré-requisito: 6º nível de nobre. Você pode gastar 2 PM para servir de inspiração. Até o início de seu próximo turno, sempre que você passar em um teste de perícia, aliados em alcance curto que fizerem um teste da mesma perícia podem usar o resultado do seu teste em vez de fazer o seu próprio."},
  {"id":"nobre-lingua-ouro","nome":"Língua de Ouro","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Pré-requisito: Língua de Prata, 8º nível de nobre. Você pode gastar uma ação padrão e 4 PM para gerar o efeito da magia Enfeitiçar com os aprimoramentos de sugerir ação e afetar todas as criaturas dentro do alcance (CD Car). Esta não é uma habilidade mágica e provém de sua capacidade de influenciar outras pessoas."},
  {"id":"nobre-lingua-prata","nome":"Língua de Prata","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Quando faz um teste de perícia baseada em Carisma, você pode gastar 2 PM para receber um bônus no teste igual a metade do seu nível."},
  {"id":"nobre-lingua-rapida","nome":"Língua Rápida","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Quando faz um teste de Diplomacia para mudar atitude como uma ação completa, você sofre uma penalidade de –5, em vez de –10."},
  {"id":"nobre-presenca-majestosa","nome":"Presença Majestosa","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Pré-requisito: 16º nível de nobre. Sua Presença Aristocrática passa a funcionar contra qualquer criatura com valor de Inteligência (passa a afetar até mesmo animais, embora continue não funcionando contra criaturas sem Int). Além disso, você pode usá-la mais de uma vez contra uma mesma criatura na mesma cena."},
  {"id":"nobre-titulo","nome":"Título","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Pré-requisito: Autoridade Feudal, 10º nível de nobre, ter conquistado terras ou realizado um serviço para um nobre que possa se tornar seu suserano. Você adquire um título de nobreza. Converse com o mestre para definir os benefícios exatos de seu título. Como regra geral, no início de cada aventura você recebe 20 TO por nível de nobre (rendimentos dos impostos) ou a ajuda de um parceiro veterano (um membro de sua corte)."},
  {"id":"nobre-voz-poderosa","nome":"Voz Poderosa","tipo":"Poder de nobre","cat":"Nobre","de":"Nobre","fonteDe":"classe","desc":"Você recebe +2 em Diplomacia e Intimidação. Suas habilidades de nobre com alcance curto passam para alcance médio."},
  {"id":"paladino-abencoado","nome":"Abençoado","tipo":"Habilidade de classe","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você soma seu Carisma no seu total de pontos de mana no 1º nível. Além disso, torna-se devoto de um deus disponível para paladinos (Azgher, Khalmyr, Lena, Lin-Wu, Marah, Tanna-Toh, Thyatis, Valkaria). Veja as regras de devotos na página 96. Ao contrário de devotos normais, você recebe dois poderes concedidos por se tornar devoto, em vez de apenas um. Como alternativa, você pode ser um paladino do bem, lutando em prol da bondade e da justiça como um todo. Não recebe nenhum Poder Concedido, mas não precisa seguir nenhuma Obrigação & Restrição (além do Código do Herói). Cultuar o bem conta como sua devoção."},
  {"id":"paladino-arma-sagrada","nome":"Arma Sagrada","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Pré-requisito: devoto de uma divindade (exceto Lena e Marah). Quando usa Golpe Divino para atacar com a arma preferida de sua divindade, o dado de dano que você rola por Golpe Divino aumenta para d12."},
  {"id":"paladino-aumento-atributo","nome":"Aumento de Atributo","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo."},
  {"id":"paladino-aura-antimagia","nome":"Aura Antimagia","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Pré-requisito: 14º nível de paladino. Enquanto sua aura estiver ativa, você e os aliados dentro da aura podem rolar novamente qualquer teste de resistência contra magia recém realizado."},
  {"id":"paladino-aura-ardente","nome":"Aura Ardente","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Pré-requisito: 10º nível de paladino. Enquanto sua aura estiver ativa, no início de cada um de seus turnos, espíritos e mortos-vivos a sua escolha dentro dela sofrem dano de luz igual a 5 + seu Carisma."},
  {"id":"paladino-aura-cura","nome":"Aura de Cura","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Pré-requisito: 6º nível de paladino. Enquanto sua aura estiver ativa, no início de seus turnos, você e os aliados a sua escolha dentro dela curam um número de PV igual a 5 + seu Carisma."},
  {"id":"paladino-aura-invencibilidade","nome":"Aura de Invencibilidade","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Pré-requisito: 18º nível de paladino. Enquanto sua aura estiver ativa, você ignora o primeiro dano que sofrer na cena. O mesmo se aplica a seus aliados dentro da aura."},
  {"id":"paladino-aura-poderosa","nome":"Aura Poderosa","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Pré-requisito: 6º nível de paladino. O raio da sua aura aumenta para 30m."},
  {"id":"paladino-bencao-justica","nome":"Bênção da Justiça","tipo":"Habilidade de classe","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"No 5º nível, escolha entre Égide Sagrada e Montaria Sagrada (cada uma está listada como uma habilidade própria). Uma vez feita, esta escolha não pode ser mudada.","nivel":5},
  {"id":"paladino-bencao-justica-egide-sagrada","nome":"Bênção da Justiça: Égide Sagrada","tipo":"Habilidade de classe","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você pode gastar uma ação de movimento e 2 PM para recobrir de energia seu escudo ou símbolo sagrado. Até o fim da cena, você e todos os aliados adjacentes somam seu Carisma na Defesa (cumulativo com outros efeitos). A partir do 11º nível, quando faz um teste de resistência contra uma magia lançada contra você, você pode gastar 5 PM para rolá-lo novamente. Se você passar no teste de resistência e a magia tiver você como único alvo, ela é revertida de volta ao conjurador (que se torna o novo alvo da magia; todas as demais características da magia, incluindo CD do teste de resistência, se mantêm)."},
  {"id":"paladino-bencao-justica-montaria-sagrada","nome":"Bênção da Justiça: Montaria Sagrada","tipo":"Habilidade de classe","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você pode gastar uma ação de movimento e 2 PM para invocar uma montaria sagrada. Veja o quadro para mais detalhes."},
  {"id":"paladino-fulgor-divino","nome":"Fulgor Divino","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Quando usa Golpe Divino, todos os inimigos em alcance curto ficam ofuscados até o início do seu próximo turno."},
  {"id":"paladino-julgamento-divino-arrependimento","nome":"Julgamento Divino: Arrependimento","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você pode gastar 2 PM para marcar um inimigo em alcance curto. Na próxima vez que esse inimigo acertar um ataque em você ou em um de seus aliados, deve fazer um teste de Vontade (CD Car). Se falhar, fica atordoado no próximo turno dele (apenas uma vez por cena)."},
  {"id":"paladino-julgamento-divino-autoridade","nome":"Julgamento Divino: Autoridade","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você pode gastar 1 PM para comandar uma criatura em alcance curto. Faça um teste de Diplomacia oposto pelo teste de Vontade do alvo. Se você vencer, ele obedece a um comando simples, como “pare” ou “largue a arma” (apenas uma vez por cena). Mental."},
  {"id":"paladino-julgamento-divino-coragem","nome":"Julgamento Divino: Coragem","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você pode gastar 2 PM para inspirar coragem em uma criatura em alcance curto, incluindo você mesmo. A criatura fica imune a efeitos de medo e recebe +2 em testes de ataque contra o inimigo com maior ND na cena."},
  {"id":"paladino-julgamento-divino-iluminacao","nome":"Julgamento Divino: Iluminação","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você pode marcar um inimigo em alcance curto. Quando acerta um ataque corpo a corpo nesse inimigo, você recebe 2 PM temporários. Você só pode proferir este julgamento uma vez por cena."},
  {"id":"paladino-julgamento-divino-justica","nome":"Julgamento Divino: Justiça","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você pode gastar 2 PM para marcar um inimigo em alcance curto. A próxima vez que esse inimigo causar dano em você ou em um de seus aliados, deve fazer um teste de Vontade (CD Car). Se falhar, sofre dano de luz igual à metade do dano que causou."},
  {"id":"paladino-julgamento-divino-libertacao","nome":"Julgamento Divino: Libertação","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você pode gastar 5 PM para cancelar uma condição negativa qualquer (como abalado, paralisado etc.) que esteja afetando uma criatura em alcance curto."},
  {"id":"paladino-julgamento-divino-salvacao","nome":"Julgamento Divino: Salvação","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você pode gastar 2 PM para marcar um inimigo em alcance curto. Até o fim da cena, quando você acerta um ataque corpo a corpo nesse inimigo, recupera 5 pontos de vida."},
  {"id":"paladino-julgamento-divino-vindicacao","nome":"Julgamento Divino: Vindicação","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você pode gastar 2 PM para marcar um inimigo que tenha causado dano a você ou a seus aliados na cena. Você recebe +1 em testes de ataque e +1d8 em rolagens de dano contra o inimigo escolhido, mas sofre –5 em testes de ataque contra quaisquer outros alvos. No pagar +1 PM para aumentar o bônus de ataque em +1 e o bônus de dano em +1d8. O efeito termina caso o alvo fique inconsciente."},
  {"id":"paladino-julgamento-divino-zelo","nome":"Julgamento Divino: Zelo","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você pode gastar 1 PM para marcar um alvo em alcance longo. Pelo restante da cena, sempre que se mover na direção desse alvo, você se move com o dobro de seu deslocamento."},
  {"id":"paladino-orar","nome":"Orar","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você aprende e pode lançar uma magia divina de 1º círculo a sua escolha. Seu atributo-chave para esta magia é Sabedoria. Você pode escolher este poder quantas vezes quiser."},
  {"id":"paladino-virtude-paladinesca-caridade","nome":"Virtude Paladinesca: Caridade","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"O custo de suas habilidades de paladino que tenham um aliado como alvo é reduzido em –1 PM."},
  {"id":"paladino-virtude-paladinesca-castidade","nome":"Virtude Paladinesca: Castidade","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você se torna imune a efeitos de encantamento e recebe +5 em testes de Intuição para perceber blefes."},
  {"id":"paladino-virtude-paladinesca-compaixao","nome":"Virtude Paladinesca: Compaixão","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Você pode usar Cura pelas Mãos em alcance curto e, para cada PM que gastar, cura 2d6+1 (em vez de 1d8+1)."},
  {"id":"paladino-virtude-paladinesca-humildade","nome":"Virtude Paladinesca: Humildade","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Na primeira rodada de um combate, você pode gastar uma ação completa para rezar e pedir orientação. Você recebe uma quantidade de PM temporários igual ao seu Carisma (duram até o fim da cena)."},
  {"id":"paladino-virtude-paladinesca-temperanca","nome":"Virtude Paladinesca: Temperança","tipo":"Poder de paladino","cat":"Paladino","de":"Paladino","fonteDe":"classe","desc":"Quando ingere um alimento, item alquímico ou poção, você consome apenas metade do item. Na prática, cada item desses rende duas “doses” para você."},
  {"id":"origem-prova-tudo","nome":"À Prova de Tudo","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Batedor","fonteDe":"origem","desc":"Você não sofre penalidade em deslocamento e Sobrevivência por clima ruim e por terreno difícil natural."},
  {"id":"origem-agua-feijao","nome":"Água no Feijão","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Fazendeiro","fonteDe":"origem","desc":"Você não sofre a penalidade de –5 e não gasta matéria-prima adicional para fabricar pratos para cinco pessoas."},
  {"id":"origem-alpinista-social","nome":"Alpinista Social","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Charlatão","fonteDe":"origem","desc":"Você pode substituir testes de Diplomacia por testes de Enganação."},
  {"id":"origem-amigo-especial","nome":"Amigo Especial","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Amigo dos Animais","fonteDe":"origem","desc":"Você recebe +5 em testes de Adestramento com animais. Além disso, possui um animal de estimação que o auxilia e o acompanha em suas aventuras. Em termos de jogo, é um parceiro que fornece +2 em uma perícia a sua escolha (exceto Luta ou Pontaria e aprovada pelo mestre) e não conta em seu limite de parceiros."},
  {"id":"origem-antigo-mestre","nome":"Antigo Mestre","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Seguidor","fonteDe":"origem","desc":"Você ainda mantém contato com o herói que costumava servir. Uma vez por aventura, ele surge para ajudá-lo por uma cena. Ele é um parceiro mestre de um tipo a sua escolha (definido ao obter este poder) que não conta em seu limite de aliados."},
  {"id":"origem-busca-interior","nome":"Busca Interior","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Eremita","fonteDe":"origem","desc":"Quando você e seus companheiros estão diante de um mistério, incapazes de prosseguir, você pode gastar 1 PM para meditar sozinho durante algum tempo e receber uma dica do mestre."},
  {"id":"origem-confissao","nome":"Confissão","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Capanga","fonteDe":"origem","desc":"Você pode usar Intimidação para interrogar sem custo e em um minuto (veja Investigação)."},
  {"id":"origem-coracao-heroico","nome":"Coração Heroico","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Herói Camponês","fonteDe":"origem","desc":"Você recebe +3 pontos de mana. Quando atinge um novo patamar (no 5º, 11º e 17º níveis), recebe +3 PM."},
  {"id":"origem-cultura-exotica","nome":"Cultura Exótica","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Forasteiro","fonteDe":"origem","desc":"Por sua diferente visão de mundo, você encontra soluções inesperadas. Quando vai fazer um teste de perícia que requer treinamento, você pode gastar 1 PM para ignorar esse requerimento para esse teste."},
  {"id":"origem-desejo-liberdade","nome":"Desejo de Liberdade","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Escravo","fonteDe":"origem","desc":"Ninguém voltará a torná-lo um escravo! Você recebe +5 em testes contra a manobra agarrar e efeitos de movimento."},
  {"id":"origem-detetive","nome":"Detetive","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Guarda","fonteDe":"origem","desc":"Você pode gastar 1 PM para substituir testes de Percepção e Intuição por testes de Investigação até o fim da cena."},
  {"id":"origem-dom-artistico","nome":"Dom Artístico","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Artista","fonteDe":"origem","desc":"Você recebe +2 em testes de Atuação, e recebe o dobro de tibares em apresentações."},
  {"id":"origem-escavador","nome":"Escavador","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Minerador","fonteDe":"origem","desc":"Você se torna proficiente em picaretas, causa +1 de dano com elas e não é afetado por terreno difícil em masmorras e subterrâneos."},
  {"id":"origem-esforcado","nome":"Esforçado","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Trabalhador","fonteDe":"origem","desc":"Você não teme trabalho duro, nem prazos apertados. Você recebe um bônus de +2 em todos os testes de perícias estendidos (incluindo perigos complexos). Sua Própria Origem Uma origem é algo que você pode mudar, negociando com o mestre, para ajustar melhor à história que você imaginou. Por exemplo, Kurt Snyder estudou como médico de Salistick — mais especificamente, como alienista. A origem Curandeiro oferece as perícias Cura e Vontade. Nesse caso, o jogador de Kurt poderia trocar uma dessas por Intuição. Outro exemplo: o suraggel paladino Agatodemo, um herói camponês, protegeu sua aldeia contra o ataque de hobgoblins que, ao fugir, deixaram cair uma arma exótica. Antes de partir da aldeia, Agatodemo treinou com essa arma. Assim, você poderia trocar seus itens iniciais pela própria arma, e pegar o poder Proficiência para saber usá-la. Até mesmo uma nova habilidade pode ser inventada, usando as outras como referência e inspiração. Você não precisa ficar preso apenas a benefícios mecânicos, como “ganhar +2 em alguma coisa”. Pense em coisas que ajudem seu grupo ou tragam mais sabor à interpretação, ou ainda algo relacionado à própria campanha — ser parente de algum NPC importante, por exemplo. Ainda, você pode inventar uma origem totalmente nova. Talvez Kaine, o Coletor, seja um guerreiro esqueleto conjurado pelo próprio necromante Vladislav, enquanto Ira Dodado é um clérigo de Nimb que começou sua carreira após matar um dragão com uma panelada, e Kadi O’ Blaine é um arcanista vindo de Magika, mundo da deusa Wynna. Lembre-se: em Arton, nenhum herói é estranho demais. Aproveite a origem para transpor para o jogo ideias que você tenha e não consiga representar com raça e classe. Em outras palavras, ela é o espaço para o jogador criar. Só não vale apelar! “Ah, eu era seguidor de um arcanista de 18º nível, então ele morreu engasgado com um pretzel e eu fiquei com as coisas mágicas dele, tudo bem?”"},
  {"id":"origem-esse-cheiro","nome":"Esse Cheiro...","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Assistente de Laboratório","fonteDe":"origem","desc":"Você recebe +2 em Fortitude e detecta automaticamente a presença (mas não a localização ou natureza) de itens alquímicos em alcance curto."},
  {"id":"origem-estoico","nome":"Estoico","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Refugiado","fonteDe":"origem","desc":"Sua condição de descanso é uma categoria acima do padrão pela situação (normal em condições ruins, confortável em condições normais e luxuosa em condições confortáveis ou melhores). Veja as regras de recuperação na página 106."},
  {"id":"origem-frutos-trabalho","nome":"Frutos do Trabalho","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Artesão","fonteDe":"origem","desc":"No início de cada aventura, você recebe até 5 itens gerais que possa fabricar num valor total de até T$ 50. Esse valor aumenta para T$ 100 no patamar veterano, T$ 300 no campeão e T$ 500 no lenda."},
  {"id":"origem-gororoba","nome":"Gororoba","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Taverneiro","fonteDe":"origem","desc":"Você não sofre a penalidade de –5 para fabricar um prato especial adicional."},
  {"id":"origem-heranca","nome":"Herança","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Herdeiro","fonteDe":"origem","desc":"Você herdou um item de preço de até T$ 1.000. Você pode escolher este poder duas vezes, para um item de até T$ 2.000."},
  {"id":"origem-influencia-militar","nome":"Influência Militar","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Soldado","fonteDe":"origem","desc":"Você fez amigos nas forças armadas. Onde houver acampamentos ou bases militares, você pode conseguir hospedagem e informações para você e seus aliados."},
  {"id":"origem-lembrancas-graduais","nome":"Lembranças Graduais","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Amnésico","fonteDe":"origem","desc":"Durante suas aventuras, em determinados momentos a critério do mestre, você pode fazer um teste de Sabedoria (CD 10) para reconhecer pessoas, criaturas ou lugares que tenha encontrado antes de perder a memória."},
  {"id":"origem-medico-campo","nome":"Médico de Campo","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Curandeiro","fonteDe":"origem","desc":"Você soma sua Sabedoria aos PV restaurados por suas habilidades e itens mundanos de cura."},
  {"id":"origem-membro-igreja","nome":"Membro da Igreja","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Acólito","fonteDe":"origem","desc":"Você consegue hospedagem confortável e informação em qualquer templo de sua divindade, para você e seus aliados."},
  {"id":"origem-mochileiro","nome":"Mochileiro","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Nômade","fonteDe":"origem","desc":"Seu limite de carga aumenta em 5 espaços."},
  {"id":"origem-negociacao","nome":"Negociação","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Mercador","fonteDe":"origem","desc":"Você pode vender itens 10% mais caro (não cumulativo com barganha)."},
  {"id":"origem-palpite-fundamentado","nome":"Palpite Fundamentado","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Estudioso","fonteDe":"origem","desc":"Quando vai fazer um teste de perícia originalmente baseada em Inteligência ou Sabedoria, você pode gastar 2 PM para substituí-la por Conhecimento."},
  {"id":"origem-pao-circo","nome":"Pão e Circo","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Gladiador","fonteDe":"origem","desc":"Por seu treino em combates de exibição, você sabe “bater sem machucar”. Pode escolher causar dano não letal sem sofrer a penalidade de –5."},
  {"id":"origem-passagem-navio","nome":"Passagem de Navio","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Marujo","fonteDe":"origem","desc":"Você consegue transporte marítimo para você e seus aliados, sem custos, desde que todos paguem com trabalho (passar em pelo menos um teste de perícia adequado durante a viagem)."},
  {"id":"origem-punguista","nome":"Punguista","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Criminoso","fonteDe":"origem","desc":"Você pode fazer testes de Ladinagem para sustento (como a perícia Ofício), mas em apenas um dia. Se passar, recebe o dobro do dinheiro, mas, se falhar, pode ter problemas com a lei (a critério do mestre)."},
  {"id":"origem-quebra-galho","nome":"Quebra-Galho","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Pivete","fonteDe":"origem","desc":"Em cidades ou metrópoles, você pode comprar qualquer item mundano não superior por metade do preço normal. Esses itens não podem ser matérias-primas e não podem ser revendidos (são velhos, sujos, furtados...)."},
  {"id":"origem-rede-contatos","nome":"Rede de Contatos","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Membro de Guilda","fonteDe":"origem","desc":"Graças à influência de sua guilda, você pode usar Diplomacia para interrogar sem custo e em um minuto (veja Investigação)."},
  {"id":"origem-sangue-azul","nome":"Sangue Azul","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Aristocrata","fonteDe":"origem","desc":"Você tem alguma influência política, suficiente para ser tratado com mais leniência pela guarda, conseguir uma audiência com o nobre local etc."},
  {"id":"origem-truque-magica","nome":"Truque de Mágica","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Circense","fonteDe":"origem","desc":"Você pode lançar Explosão de Chamas, Hipnotismo e Queda Suave, mas apenas com o aprimoramento Truque. Esta não é uma habilidade mágica — os efeitos provêm de prestidigitação."},
  {"id":"origem-vendedor-carcacas","nome":"Vendedor de Carcaças","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Mateiro","fonteDe":"origem","desc":"Você pode extrair recursos de criaturas em um minuto, em vez de uma hora, e recebe +5 no teste."},
  {"id":"origem-vida-rustica","nome":"Vida Rústica","tipo":"Poder único de origem","cat":"Poderes Únicos","de":"Selvagem","fonteDe":"origem","desc":"Você come coisas que fariam um avestruz vomitar (sendo imune a efeitos prejudiciais de itens ingeríveis) e também consegue descansar nos lugares mais desconfortáveis (mesmo dormindo ao relento, sua recuperação de PV e PM nunca é inferior a seu próprio nível)."}
];
